'use client';

import {FormEvent,useCallback,useEffect,useMemo,useState} from 'react';
import PasswordSettings from './PasswordSettings';

type MainModule='staff'|'tasks'|'violations'|'checklists'|'plans'|'reports'|'kpi'|'alerts'|'settings';
type FormModule=MainModule|'reminders'|'issues'|'violationError'|'checklistForm'|'checklistCriterion'|'feedback'|'rule'|'taskApproval';
type AnyRecord=Record<string,any>;
function recordArray(value:any):AnyRecord[]{return Array.isArray(value)?value.filter(item=>item&&typeof item==='object') as AnyRecord[]:[];}

const BASE_DEPARTMENTS=['VỆ SINH MÔI TRƯỜNG','ĐỒ VẢI','ĐỒ VẢI - PHÒNG VIP','GIÁM SÁT','DỤNG CỤ','VI PHẠM CHUNG'];
const MODULES:Array<{key:MainModule;label:string;number:string}>=([
 ['tasks','GIAO VIỆC & NHẮC VIỆC','1'],['violations','LỖI ĐỘT XUẤT / VI PHẠM','2'],
 ['plans','KẾ HOẠCH TUẦN / THÁNG','3'],['checklists','BẢNG KIỂM GIÁM SÁT','4'],['reports','BÁO CÁO TỔNG HỢP MỚI','5'],
 ['alerts','CẢNH BÁO & LỊCH CÔNG VIỆC','7'],['kpi','KPI 100 ĐIỂM','8'],['settings','CÀI ĐẶT','9']
] as Array<[MainModule,string,string]>).map(([key,label,number])=>({key,label,number}));
const STAFF_MODULE={key:'staff' as MainModule,label:'NHÂN SỰ & HỢP ĐỒNG',number:'6'};
const MODULE_LABELS:Record<string,string>={...Object.fromEntries(MODULES.map(x=>[x.key,x.label])),staff:STAFF_MODULE.label};
MODULE_LABELS.kpi='8. KPI 100 ĐIỂM';

const REPORT_SECTIONS=[
 {id:'weekly',label:'1. KẾ HOẠCH TUẦN CỦA BỘ PHẬN'},
 {id:'monthly',label:'2. KẾ HOẠCH THÁNG CỦA BỘ PHẬN'},
 {id:'tasks',label:'3. CÔNG VIỆC TRỌNG ĐIỂM & ĐỘT XUẤT'},
 {id:'overview',label:'4. CHỈ SỐ TỔNG QUAN'},
 {id:'checklists',label:'5. PHÂN TÍCH BẢNG KIỂM'},
 {id:'routine',label:'6. THỐNG KÊ & PHÂN TÍCH LỖI THƯỜNG QUY'},
 {id:'sudden',label:'7. THỐNG KÊ LỖI ĐỘT XUẤT / VI PHẠM'},
 {id:'matrix',label:'8. MA TRẬN THEO TỪNG PHIẾU GIÁM SÁT'},
 {id:'kpi',label:'9. KPI 100 ĐIỂM — ĐÚNG LOGIC MENU KPI'},
 {id:'incidents',label:'10. NHẬT KÝ SỰ CỐ'},
 {id:'issues',label:'11. TỒN TẠI KHÁC & KIẾN NGHỊ'},
 {id:'next-week',label:'12. DANH SÁCH KẾ HOẠCH TUẦN SAU'}
];
const REPORT_SECTION_IDS=REPORT_SECTIONS.map(x=>x.id);

function monthBounds(){const d=new Date();const from=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;const last=new Date(d.getFullYear(),d.getMonth()+1,0);return {from,to:`${last.getFullYear()}-${String(last.getMonth()+1).padStart(2,'0')}-${String(last.getDate()).padStart(2,'0')}`};}
const PLAN_WEEKDAYS=[{value:'1',label:'Thứ 2'},{value:'2',label:'Thứ 3'},{value:'3',label:'Thứ 4'},{value:'4',label:'Thứ 5'},{value:'5',label:'Thứ 6'},{value:'6',label:'Thứ 7'},{value:'7',label:'Chủ nhật'}];
function localYmd(value:Date){return `${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}-${String(value.getDate()).padStart(2,'0')}`;}
function planWeekdayValue(value:any){const raw=text(value).slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(raw))return '';const date=new Date(`${raw}T00:00:00`);if(Number.isNaN(date.getTime()))return '';return String(date.getDay()===0?7:date.getDay());}
function planWeekdayLabel(value:any){const found=PLAN_WEEKDAYS.find(item=>item.value===planWeekdayValue(value));return found?.label||'';}
function planDateForWeekday(anchor:any,weekday:any){const raw=text(anchor).slice(0,10);const date=/^\d{4}-\d{2}-\d{2}$/.test(raw)?new Date(`${raw}T00:00:00`):new Date();const target=Number(weekday)||Number(planWeekdayValue(localYmd(date)))||1;const current=Number(planWeekdayValue(localYmd(date)))||1;date.setDate(date.getDate()+target-current);return localYmd(date);}
function planDefaultDates(type:any,anchor:any){const normalized=normalize(type);const raw=text(anchor).slice(0,10);const date=/^\d{4}-\d{2}-\d{2}$/.test(raw)?new Date(`${raw}T00:00:00`):new Date();if(normalized.includes('thang')){const first=new Date(date.getFullYear(),date.getMonth(),1);const last=new Date(date.getFullYear(),date.getMonth()+1,0);return {from:localYmd(first),to:localYmd(last)};}const selected=planDateForWeekday(localYmd(date),planWeekdayValue(localYmd(date)));return {from:selected,to:selected};}
function text(value:any){if(value==null)return '';if(typeof value==='string'||typeof value==='number'||typeof value==='boolean')return String(value);try{return JSON.stringify(value)}catch{return '[Dữ liệu]';}}
function formatDate(value:any){const raw=text(value);return raw?raw.slice(0,10):'—';}
function normalize(value:any){return text(value).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');}
function statusClass(value:any){const v=normalize(value);if(v.includes('hoan thanh')||v.includes('da khac phuc')||v.includes('da xong')||v==='dong')return 'ok';if(v.includes('qua han')||v.includes('khong dat')||v.includes('kem'))return 'danger';if(v.includes('dang')||v.includes('cho')||v.includes('chua'))return 'warn';return 'neutral';}
function alertVisualClass(alert:AnyRecord){const kind=normalize(alert?.kind);if(kind==='cong viec moi giao')return 'new-task';if(kind==='cong viec hom nay')return 'today-task';if(kind==='nghi phep')return 'leave-plan-alert';return statusClass(alert?.level);}
function isViolationAlert(alert:AnyRecord){return normalize(alert?.kind)==='vi pham chua xu ly';}
function enabledFlag(value:any){if(typeof value==='boolean')return value;return ['true','1','yes','on','bat','bật','co','có'].includes(normalize(value));}
function isWaitingManager(value:any){return ['cho phe duyet','cho quan ly phan hoi','cho quan ly phe duyet'].includes(normalize(value));}
function approvalLabel(value:any){const v=normalize(value);if(isWaitingManager(value))return 'CHỜ PHÊ DUYỆT';if(v==='chua xin y kien'||v==='chua yeu cau')return 'CHƯA YÊU CẦU';return text(value);}
function approvalHistory(value:any):AnyRecord[]{if(Array.isArray(value))return value;const raw=text(value);if(!raw)return [];try{const parsed=JSON.parse(raw);return Array.isArray(parsed)?parsed:[]}catch{return []}}
function approvalActionForAlert(alert:AnyRecord){const kind=normalize(alert?.kind);if(alert?.target!=='tasks')return '';if(isWaitingManager(alert?.approvalStatus)||kind.includes('phe duyet')||kind.includes('xin y kien'))return 'review';if(kind.includes('phan hoi')||normalize(alert?.approvalStatus).includes('yeu cau bo sung')||normalize(alert?.approvalStatus).includes('tu choi'))return 'feedback';return '';}
function paramsFor(module:MainModule,filters:AnyRecord){const p=new URLSearchParams({module});['from','to','department','person','manager','title','priority','status','approvalStatus','formCode','type'].forEach(k=>{if(filters[k])p.set(k,filters[k]);});['assignees','statuses','reportSection'].forEach(k=>{if(Array.isArray(filters[k]))p.set(k,JSON.stringify(filters[k]));});return p.toString();}
function Badge({value}:{value:any}){return <span className={'status-badge '+statusClass(value)}>{text(value)||'—'}</span>;}
function ApprovalSteps({status,action,compact=false}:{status?:any;action?:string;compact?:boolean}){
 const requestFlow=action==='request';const waitingManager=!requestFlow&&(action==='review'||isWaitingManager(status));const waitingEmployee=!requestFlow&&(action==='feedback'||['da phe duyet','yeu cau bo sung','tu choi'].includes(normalize(status)));
 const steps=waitingManager?['Mở “Chi tiết giao việc” và đọc toàn bộ nội dung, thời hạn, ghi chú cùng minh chứng.','Kiểm tra kết quả thực hiện và tài liệu/ảnh minh chứng trước khi quyết định.','Chọn “Đánh giá quản lý hiện tại”, chọn kết quả phê duyệt và nhập ý kiến quản lý.','Bấm “Lưu đánh giá & phê duyệt”; nếu chưa đủ thì chọn “Yêu cầu bổ sung” để chuyển lại cho nhân viên.']:waitingEmployee?['Mở chi tiết để đọc đánh giá và ý kiến quản lý mới nhất.','Thực hiện bổ sung hoặc giải trình theo yêu cầu; cập nhật ghi chú và minh chứng nếu cần.','Bấm “Gửi phản hồi” để hoàn tất vòng phản hồi và chuyển lại cho quản lý.']:['Chọn đúng người quản lý theo cột Chức vụ.','Nhập rõ nội dung cần xem xét, kết quả và minh chứng liên quan.','Bấm “Gửi xin phê duyệt”; hệ thống sẽ tạo cảnh báo cho quản lý đã chọn.'];
 return <div className={`approval-steps${compact?' compact':''}`}><strong>QUY TRÌNH THỰC HIỆN</strong><ol>{steps.map((step,index)=><li key={index}>{step}</li>)}</ol></div>;
}

function SmartMulti({options,value,onChange,placeholder}:{options:string[];value:string[];onChange:(values:string[])=>void;placeholder:string}){
 const[open,setOpen]=useState(false);const[query,setQuery]=useState('');const filtered=options.filter(x=>!query||normalize(x).includes(normalize(query)));
 return <div className="smart-picker"><button type="button" className="smart-picker-toggle" onClick={()=>setOpen(x=>!x)}>{value.length?`${value.length} đã chọn`:placeholder}<span>⌄</span></button>{open&&<div className="smart-picker-menu"><input placeholder="Gõ để lọc..." value={query} onChange={e=>setQuery(e.target.value)}/><div className="smart-picker-options">{filtered.map(option=><label key={option}><input type="checkbox" checked={value.includes(option)} onChange={e=>onChange(e.target.checked?[...value,option]:value.filter(x=>x!==option))}/><span>{option}</span></label>)}</div><button type="button" className="smart-picker-clear" onClick={()=>onChange([])}>Xóa lựa chọn</button></div>}</div>;
}

function ReportSectionPicker({value,onChange}:{value:string[];onChange:(values:string[])=>void}){
 const allSelected=value.length===REPORT_SECTION_IDS.length;
 const toggle=(id:string,checked:boolean)=>onChange(checked?[...new Set([...value,id])]:value.filter(x=>x!==id));
 return <fieldset className="report-section-picker"><legend>CHỌN MỤC BÁO CÁO HIỂN THỊ</legend><div className="report-section-options">{REPORT_SECTIONS.map(section=><label key={section.id}><input type="checkbox" checked={value.includes(section.id)} onChange={e=>toggle(section.id,e.target.checked)}/><span>{section.label}</span></label>)}</div><div className="report-section-actions"><button type="button" onClick={()=>onChange(allSelected?[]:REPORT_SECTION_IDS)}>{allSelected?'BỎ CHỌN TẤT CẢ':'CHỌN TẤT CẢ'}</button><small>{value.length}/{REPORT_SECTION_IDS.length} mục đang hiển thị</small></div></fieldset>;
}

function SmartStaffPicker({staff,value,onChange,department='',placeholder='Gõ tên để lọc',showPosition=false}:{staff:AnyRecord[];value:any;onChange:(value:string)=>void;department?:string;placeholder?:string;showPosition?:boolean}){
 const[open,setOpen]=useState(false);const[query,setQuery]=useState('');const selected=text(value);const selectedStaff=staff.find(x=>sameValue(x.name,selected));const display=showPosition&&selectedStaff?[selectedStaff.name,selectedStaff.position].filter(Boolean).join(' · '):selected;const options=staff.filter(x=>!department||normalize(x.department)===normalize(department)||normalize(x.name)===normalize(selected));const filtered=options.filter(x=>!query||normalize(x.id).includes(normalize(query))||normalize(x.name).includes(normalize(query))||normalize(x.department).includes(normalize(query))||normalize(x.position).includes(normalize(query)));
 return <div className="smart-staff-picker"><input value={open?query:display} placeholder={placeholder} autoComplete="off" onFocus={()=>{setOpen(true);setQuery('')}} onChange={e=>{onChange('');setOpen(true);setQuery(e.target.value)}} onBlur={()=>setTimeout(()=>setOpen(false),150)}/>{open&&<div className="smart-staff-menu">{filtered.length?filtered.map(x=><button type="button" key={x.id||x.name} onMouseDown={e=>e.preventDefault()} onClick={()=>{onChange(x.name);setQuery('');setOpen(false)}}><b>{x.name}</b><small>{[x.id,x.department,x.position||'Chưa có Chức vụ'].filter(Boolean).join(' · ')}</small></button>):<div className="smart-staff-empty">Không tìm thấy nhân sự phù hợp.</div>}</div>}</div>;
}

function SmartOptionPicker({options,value,onChange,placeholder='Gõ để lọc → chọn'}:{options:string[];value:any;onChange:(value:string)=>void;placeholder?:string}){
 const[open,setOpen]=useState(false);const[query,setQuery]=useState('');const selected=text(value);const values=[...new Set(options.map(text).filter(Boolean))];const filtered=values.filter(option=>!query||normalize(option).includes(normalize(query)));
 return <div className="smart-staff-picker"><input value={open?query:selected} placeholder={placeholder} autoComplete="off" aria-label={placeholder} onFocus={()=>{setOpen(true);setQuery('')}} onChange={e=>{onChange('');setOpen(true);setQuery(e.target.value)}} onBlur={()=>setTimeout(()=>setOpen(false),150)}/>{open&&<div className="smart-staff-menu">{filtered.length?filtered.map(option=><button type="button" key={option} onMouseDown={e=>e.preventDefault()} onClick={()=>{onChange(option);setQuery('');setOpen(false)}}><b>{option}</b></button>):<div className="smart-staff-empty">Không tìm thấy lựa chọn phù hợp.</div>}</div>}</div>;
}

function SmartErrorPicker({errors,value,selectedName,onSelect,onClear,placeholder='Gõ tên hoặc mã lỗi để lọc'}:{errors:AnyRecord[];value:any;selectedName?:any;onSelect:(error:AnyRecord)=>void;onClear:()=>void;placeholder?:string}){
 const[open,setOpen]=useState(false);const[query,setQuery]=useState('');const selected=errors.find(x=>normalize(x.id)===normalize(value));const display=selected?[selected.id,selected.name].filter(Boolean).join(' - '):value?(selectedName?[value,selectedName].join(' - '):text(value)):'';const activeErrors=errors.filter(x=>!['ngung','tam dung','khong hoat dong'].some(status=>normalize(x.status).includes(status)));const filtered=activeErrors.filter(x=>!query||[x.id,x.name,x.department,x.level].some(v=>normalize(v).includes(normalize(query))));
 return <div className="smart-staff-picker"><input value={open?query:display} placeholder={placeholder} autoComplete="off" onFocus={()=>{setOpen(true);setQuery('')}} onChange={e=>{onClear();setOpen(true);setQuery(e.target.value)}} onBlur={()=>setTimeout(()=>setOpen(false),150)}/>{open&&<div className="smart-staff-menu">{filtered.length?filtered.map(x=><button type="button" key={x.id||x.name} onMouseDown={e=>e.preventDefault()} onClick={()=>{onSelect(x);setQuery('');setOpen(false)}}><b>{[x.id,x.name].filter(Boolean).join(' - ')}</b><small>{[x.department,x.level,x.score!=null?`Trừ ${x.score} điểm`:'' ].filter(Boolean).join(' · ')}</small></button>):<div className="smart-staff-empty">Không tìm thấy lỗi phù hợp.</div>}</div>}</div>;
}

function Field({label,value,onChange,type='text',children,wide=false,required=false}:{label:string;value:any;onChange:(value:string)=>void;type?:string;children?:React.ReactNode;wide?:boolean;required?:boolean}){return <label className={wide?'form-field wide':'form-field'}>{label}{children||<input type={type} value={text(value)} onChange={e=>onChange(e.target.value)} required={required}/>}</label>;}
function formIsSaving(form:AnyRecord){return Boolean(form.__saving);}

export default function Home(){
 const bounds=useMemo(monthBounds,[]);const[authenticated,setAuthenticated]=useState<boolean|null>(null);const[active,setActive]=useState<MainModule|null>(null);const[payload,setPayload]=useState<AnyRecord>({rows:[],staff:[],departments:[]});const[homeAlerts,setHomeAlerts]=useState<AnyRecord[]>([]);const[homeStaff,setHomeStaff]=useState<AnyRecord[]>([]);const[health,setHealth]=useState<AnyRecord|null>(null);const[appSettings,setAppSettings]=useState({unitName:'BỆNH VIỆN 115',softwareName:'HỆ THỐNG QUẢN LÝ KSNK',logoUrl:''});const[loading,setLoading]=useState(false);const[error,setError]=useState('');const[loginError,setLoginError]=useState('');const[refresh,setRefresh]=useState(0);const[modal,setModal]=useState<AnyRecord|null>(null);const[modalError,setModalError]=useState('');const[form,setForm]=useState<AnyRecord>({});const[pendingAlert,setPendingAlert]=useState<AnyRecord|null>(null);const[menuOpen,setMenuOpen]=useState(true);
 const[filters,setFilters]=useState<AnyRecord>({from:bounds.from,to:bounds.to,department:'',person:'',manager:'',title:'',priority:'',status:'',approvalStatus:'',assignees:[],statuses:[],formCode:'',type:'TUẦN',reportSection:REPORT_SECTION_IDS});
 useEffect(()=>{fetch('/api/health',{cache:'no-store'}).then(r=>r.json()).then(setHealth).catch(()=>setHealth({ok:false}));fetch('/api/auth',{cache:'no-store'}).then(r=>r.json()).then(j=>setAuthenticated(Boolean(j.authenticated))).catch(()=>setAuthenticated(false));},[]);
 useEffect(()=>{if(authenticated!==true)return;const loadSettings=async()=>{try{const[generalResponse,logoResponse]=await Promise.all([fetch('/api/settings/general',{cache:'no-store'}),fetch('/api/settings/logo',{cache:'no-store'})]);const general=await generalResponse.json();const logo=await logoResponse.json();if(general.ok)setAppSettings({unitName:general.unitName,softwareName:general.softwareName,logoUrl:logo.ok?logo.logoUrl||'':''});}catch{ /* Settings are optional during the first render. */ }};void loadSettings();window.addEventListener('ksnk-general-settings-updated',loadSettings);return()=>window.removeEventListener('ksnk-general-settings-updated',loadSettings);},[authenticated,refresh]);
 const load=useCallback(async()=>{if(!authenticated||!active||active==='settings')return;setLoading(true);setError('');try{const r=await fetch('/api/modules?'+paramsFor(active,filters),{cache:'no-store'});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.detail||j.error||'Không tải được dữ liệu');setPayload(j);}catch(e){setError(e instanceof Error?e.message:'Không tải được dữ liệu');setPayload({rows:[],staff:[],departments:[]});}finally{setLoading(false);}},[authenticated,active,JSON.stringify(filters),refresh]);
 useEffect(()=>{void load();},[load]);
 const loadHomeAlerts=useCallback(async()=>{if(!authenticated||active)return;try{const response=await fetch('/api/modules?module=alerts',{cache:'no-store'});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||result.detail||'Không tải được cảnh báo mới nhất');setHomeAlerts(recordArray(result.rows));setHomeStaff(recordArray(result.staff));}catch(error){console.error('[alerts] refresh failed',error);}},[authenticated,active]);
 useEffect(()=>{void loadHomeAlerts();if(!authenticated||active)return;const refreshVisible=()=>{if(document.visibilityState!=='hidden')void loadHomeAlerts();};const interval=window.setInterval(refreshVisible,30000);window.addEventListener('focus',refreshVisible);document.addEventListener('visibilitychange',refreshVisible);return()=>{window.clearInterval(interval);window.removeEventListener('focus',refreshVisible);document.removeEventListener('visibilitychange',refreshVisible);};},[loadHomeAlerts,refresh]);
 const departments=useMemo<string[]>(()=>{const values=(Array.isArray(payload.departments)&&payload.departments.length?payload.departments:BASE_DEPARTMENTS) as string[];return [...new Set<string>(values.filter(Boolean))].sort((a,b)=>a.localeCompare(b,'vi'));},[payload.departments]);
 const staffNames=useMemo(()=>((payload.staff||[]) as AnyRecord[]).map(x=>x.name).filter(Boolean),[payload.staff]);
 function setFilter(name:string,value:any){setFilters((prev:AnyRecord)=>({...prev,[name]:value}));}
 function openModule(key:MainModule){setActive(key);setError('');setPayload({rows:[],staff:[],departments:[]});}
 function openAlert(alert:AnyRecord){setPendingAlert(alert);setFilters((prev:AnyRecord)=>({...prev,from:'',to:'',department:alert.department||prev.department,person:alert.person||prev.person,manager:alert.managerName||prev.manager,approvalStatus:alert.approvalStatus||prev.approvalStatus}));const target=alert.target==='plans'||alert.target==='issues'?'plans':alert.target==='staff'?'staff':alert.target==='alerts'?'alerts':alert.target==='violations'?'violations':alert.target==='checklists'?'checklists':'tasks';openModule(target);}
 function filterAlertManager(managerName:string){setPendingAlert(null);setFilters((prev:AnyRecord)=>({...prev,from:'',to:'',manager:managerName,approvalStatus:'CHỜ PHÊ DUYỆT'}));openModule('alerts');}
 function openCreate(key:FormModule,initial:AnyRecord={}){
  const today=new Date().toISOString().slice(0,10);let next:AnyRecord={};
  if(key==='tasks')next={taskId:`CV${Date.now()}`,department:filters.department||'',assigner:'',priority:'TRUNG BÌNH',status:'CHƯA BẮT ĐẦU',evalStatus:'CHƯA BẮT ĐẦU',startDate:today};
  if(key==='reminders')next={reminderId:`NV${Date.now()}`,date:today,status:'CHƯA THỰC HIỆN',daily:false};
  if(key==='staff')next={status:'Đang làm việc',annualLeaveEntitlement:''};
  if(key==='violations')next={id:`VP${Date.now()}`,date:today,status:'Chưa xử lý'};
  if(key==='plans'){const type=text(filters.type||'TUẦN').toUpperCase();const dates=planDefaultDates(type,type==='THÁNG'?(filters.from||today):today);next={id:'',type,weekday:type==='TUẦN'?planWeekdayValue(dates.from):'',fromDate:dates.from,toDate:dates.to,status:'CHƯA BẮT ĐẦU'};}
  if(key==='issues')next={id:`TT${Date.now()}`,date:today,status:'CHƯA KHẮC PHỤC'};
  if(key==='reports')next={opinionId:`YK${Date.now()}`,fromDate:filters.from,toDate:filters.to,department:filters.department,status:'Đã lưu'};
  if(key==='checklists')next={date:today,details:[]};
  if(key==='checklistForm')next={status:'Hoạt động'};
  if(key==='checklistCriterion')next={status:'Hoạt động',allowImage:'Có',order:1};
  if(key==='violationError')next={status:'Hoạt động',level:'Nhắc nhở',score:0};
  if(key==='feedback')next={from:filters.from,to:filters.to,department:filters.department,person:filters.person};
  if(key==='rule')next={status:'Hoạt động',color:'#6C757D'};
  next={...next,...initial};
  if(key==='checklists'&&initial.formCode){const selected=(payload.forms||[]).find((item:AnyRecord)=>sameValue(item.code,initial.formCode));next.formName=selected?.name||'';next.department=selected?.department||next.department||'';next.details=(payload.criteria||[]).filter((item:AnyRecord)=>sameValue(item.formCode,initial.formCode)).sort((a:AnyRecord,b:AnyRecord)=>Number(a.order||0)-Number(b.order||0)).map((item:AnyRecord)=>({criterionCode:item.id,group:item.group,content:item.content,detail:item.detail,order:item.order,allowImage:item.allowImage||'Có',result:'',note:''}));}
  setModalError('');setForm(next);setModal({module:key});
 }
 function openEdit(key:FormModule,row:AnyRecord){setModalError('');setForm({...row,__module:key});setModal({module:key,row_no:row.row_no,source:row});}
 function change(name:string,value:any){setForm((prev:AnyRecord)=>({...prev,[name]:value}));}
 async function save(e:FormEvent){
  e.preventDefault();if(!modal)return;setError('');setModalError('');setForm(prev=>({...prev,__saving:true}));
  try{
   const current=e.currentTarget as HTMLFormElement;
   const imageInput=current.elements.namedItem('evidenceImageFile') as HTMLInputElement|null;
   const documentInput=current.elements.namedItem('evidenceDocumentFile') as HTMLInputElement|null;
   const legacyInput=current.elements.namedItem('evidenceFile') as HTMLInputElement|null;
   const imageFile=imageInput?.files?.[0];const documentFile=documentInput?.files?.[0];const legacyFile=legacyInput?.files?.[0];
   const evidenceFiles=[imageFile,documentFile,legacyFile].filter((file,index,array):file is File=>Boolean(file)&&array.indexOf(file)===index);
   const checklistDetailFiles=modal.module==='checklists'?Array.from(current.querySelectorAll<HTMLInputElement>('input[data-checklist-detail-image]')).flatMap(input=>{const file=input.files?.[0];return file?[{file,criterion:text(input.dataset.criterionCode)}]:[]}):[];
   if(modal.module==='tasks'&&!text(form.assigner))throw new Error('Vui lòng chọn Người giao việc từ danh sách nhân sự trước khi lưu.');
   if(modal.module==='taskApproval'&&text(form.approvalAction||'request')==='request'&&!text(form.managerName))throw new Error('Vui lòng chọn Người quản lý phê duyệt theo Chức vụ trước khi gửi.');
   if(modal.module==='violations'&&(!form.person||!form.staffId||!form.errorId||!form.recorder))throw new Error('Vui lòng chọn nhân viên, lỗi vi phạm và người ghi nhận từ danh mục.');
   if(modal.module==='plans'){const from=text(form.fromDate).slice(0,10);const to=text(form.toDate).slice(0,10);if(!from||!to)throw new Error('Kế hoạch phải có đầy đủ ngày thực hiện.');if(to<from)throw new Error('Đến ngày không được trước Từ ngày.');if(normalize(form.type||'TUẦN')==='tuan'&&form.weekday&&planWeekdayValue(from)!==String(form.weekday))throw new Error('Thứ đã chọn không khớp với ngày thực hiện. Hãy chọn lại Thứ hoặc ngày.');}
   if(modal.module==='checklists'){
    const details=Array.isArray(form.details)?form.details as AnyRecord[]:[];
    if(!form.formCode||!form.formName)throw new Error('PHẢI CHỌN PHIẾU GIÁM SÁT trước khi lưu.');
    if(!details.length)throw new Error('Phiếu chưa có tiêu chí để chấm.');
    for(const [index,item] of details.entries()){
     const result=normalize(item.result);
     if(!result)throw new Error(`CHƯA CHỌN KẾT QUẢ tại tiêu chí số ${index+1}. Hệ thống không cho lưu phiếu chưa chấm đủ.`);
     if(!['dat','khong dat','kem','khong ap dung','na','n/a'].includes(result))throw new Error(`KẾT QUẢ KHÔNG HỢP LỆ tại tiêu chí số ${index+1}.`);
     if(['khong dat','kem'].includes(result)&&!text(item.note))throw new Error(`TIÊU CHÍ SỐ ${index+1} KHÔNG ĐẠT/KÉM phải có ghi chú lỗi trước khi lưu.`);
    }
   }
   const body:AnyRecord=modal.module==='taskApproval'?{module:'tasks',op:'approval',action:form.approvalAction||'request',row_no:modal.row_no,...form}:{module:modal.module,row_no:modal.row_no,...form};
   if(modal.module==='taskApproval'&&form.approvalAction==='review')body.approvalStatus=form.approvalDecision||'';
   if(modal.module==='kpi'){body.op='save_report';body.fromDate=filters.from;body.toDate=filters.to;body.department=filters.department;body.person=filters.person;}
   if(['tasks','violations','reminders'].includes(modal.module)){const image=imageFile||(legacyFile&&legacyFile.type.startsWith('image/')?legacyFile:undefined);const document=documentFile||(legacyFile&&!legacyFile.type.startsWith('image/')?legacyFile:undefined);if(image)body.imageName=image.name;if(document)body.documentName=document.name;}
   if(modal.module==='checklists')body.data={...form,imageName:imageFile?.name,documentName:documentFile?.name};
   const response=await fetch('/api/modules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json();
   if(!response.ok||!result.ok)throw new Error(result.error||'Không lưu được dữ liệu');
   if(evidenceFiles.length&&['tasks','violations','reminders','checklists'].includes(modal.module)){for(const file of evidenceFiles){const evidence=new FormData();evidence.append('file',file);evidence.append('module',modal.module);evidence.append('legacy_id',String(result.id||form.taskId||form.id||`ROW${result.row_no}`));const upload=await fetch('/api/evidence',{method:'POST',body:evidence});const uploadResult=await upload.json();if(!upload.ok||!uploadResult.ok)throw new Error(uploadResult.error||'Đã lưu dữ liệu nhưng không tải được tài liệu minh chứng');}}
   if(checklistDetailFiles.length&&result.id){for(const item of checklistDetailFiles){const evidence=new FormData();evidence.append('file',item.file);evidence.append('module','checklists');evidence.append('legacy_id',`${result.id}:${item.criterion||'criterion'}`);const upload=await fetch('/api/evidence',{method:'POST',body:evidence});const uploadResult=await upload.json();if(!upload.ok||!uploadResult.ok)throw new Error(uploadResult.error||'Đã lưu phiếu nhưng không tải được ảnh lỗi của tiêu chí');}}
   setModal(null);setModalError('');await load();
  }catch(e){const message=e instanceof Error?e.message:'Không lưu được dữ liệu';if(['checklists','tasks','taskApproval'].includes(modal.module))setModalError(message);else setError(message);}finally{setForm(prev=>({...prev,__saving:false}));}
 }
 async function remove(module:FormModule,row:AnyRecord){const warning=module==='checklists'?'Xóa phiếu giám sát này sẽ xóa cả chi tiết chấm và ảnh minh chứng liên quan. Bạn có chắc chắn muốn tiếp tục?':'Xóa bản ghi này?';if(!window.confirm(warning))return;try{const r=await fetch('/api/modules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module,op:'delete',row_no:row.row_no,type:row.type})});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Không xóa được');await load();}catch(e){setError(e instanceof Error?e.message:'Không xóa được');}}
 function editLeaveEntry(row:AnyRecord,item:AnyRecord){openEdit('staff',{...row,__leaveEntry:true,__leaveAction:'edit',__leaveId:item.id,leaveDateFrom:item.fromDate,leaveDateTo:item.toDate,leaveDays:item.days??item.leaveDays??item['Số ngày nghỉ']??'',leaveNote:item.note||''});}
 async function removeLeaveEntry(row:AnyRecord,item:AnyRecord){if(!window.confirm(`Xóa lần nghỉ phép ${formatDate(item.fromDate)} → ${formatDate(item.toDate)} của ${row.name||'nhân sự'}?`))return;try{const r=await fetch('/api/modules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:'staff',op:'save',row_no:row.row_no,data:row.data,...row,__leaveAction:'delete',leaveId:item.id})});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Không xóa được lần nghỉ phép');setModal(null);setModalError('');await load();}catch(e){setModalError(e instanceof Error?e.message:'Không xóa được lần nghỉ phép');}}
 async function planAction(op:string,row:AnyRecord){if(op==='carry'){const label=normalize(row.type).includes('thang')?'tháng sau':'tuần sau';if(!window.confirm(`Chuyển kế hoạch này sang ${label}? Bản kế hoạch cũ vẫn được giữ để tra cứu lịch sử.`))return;}try{const r=await fetch('/api/modules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:'plans',op,row_no:row.row_no,type:row.type,id:row.id})});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Không cập nhật được kế hoạch');await load();}catch(e){setError(e instanceof Error?e.message:'Không cập nhật được kế hoạch');}}
  async function toggleReminder(row:AnyRecord,daily:boolean){try{const r=await fetch('/api/modules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:'reminders',op:'daily',row_no:row.row_no,daily})});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Không cập nhật được nhắc hàng ngày');await load();setRefresh(x=>x+1);}catch(e){setError(e instanceof Error?e.message:'Không cập nhật được nhắc hàng ngày');}}
 async function inlineUpdate(body:AnyRecord){try{const r=await fetch('/api/modules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:'reports',op:'inline',...body})});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Không cập nhật được báo cáo');await load();}catch(e){setError(e instanceof Error?e.message:'Không cập nhật được báo cáo');}}
 function resetFilters(){setFilters({from:bounds.from,to:bounds.to,department:'',person:'',manager:'',title:'',priority:'',status:'',approvalStatus:'',assignees:[],statuses:[],formCode:'',type:'TUẦN',reportSection:REPORT_SECTION_IDS});}
  useEffect(()=>{if(!pendingAlert||loading||!active)return;if(pendingAlert.target==='staff'&&!pendingAlert.row_no&&!pendingAlert.id){setPendingAlert(null);return;}const source=pendingAlert.target==='reminders'?(payload.reminders||[]):pendingAlert.target==='issues'?(payload.issues||[]):(payload.rows||[]);const match=source.find((x:AnyRecord)=>x.row_no===pendingAlert.row_no||x.id===pendingAlert.id||x.taskId===pendingAlert.id);if(match){const approvalAction=approvalActionForAlert(pendingAlert);const editModule=(approvalAction?'taskApproval':pendingAlert.target==='reminders'?'reminders':pendingAlert.target==='issues'?'issues':pendingAlert.target==='staff'?'staff':active) as FormModule;openEdit(editModule,approvalAction?{...match,approvalAction}:match);setPendingAlert(null);}},[pendingAlert,loading,active,payload]);
 if(authenticated===null)return <div className="login-screen"><div className="login-card"><b>Đang kiểm tra phiên đăng nhập...</b></div></div>;
 if(!authenticated)return <div className="login-screen"><form className="login-card" onSubmit={async e=>{e.preventDefault();setLoginError('');const fd=new FormData(e.currentTarget);const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:fd.get('password')})});const j=await r.json();if(r.ok)setAuthenticated(true);else setLoginError(j.error||'Không đăng nhập được');}}><h1>HỆ THỐNG QUẢN LÝ KSNK</h1><p>Nhập mật khẩu quản trị để tiếp tục</p><input type="password" name="password" placeholder="Mật khẩu" required autoFocus/>{loginError&&<div className="error-box">{loginError}</div>}<button>ĐĂNG NHẬP</button></form></div>;
 return <div className={'app-shell '+(menuOpen?'menu-is-open':'menu-is-closed')}><header className="app-header"><button type="button" className="menu-toggle" aria-label={menuOpen?'Thu gọn thanh menu':'Mở thanh menu'} onClick={()=>setMenuOpen(x=>!x)}>☰</button><div className="hospital-brand">{appSettings.logoUrl?<img className="brand-image" src={appSettings.logoUrl} alt="Logo hệ thống"/>:<span className="brand-image-placeholder" aria-hidden="true"/>}<div><h1>{appSettings.softwareName}</h1><p>{appSettings.unitName}</p></div></div></header><aside className="side-menu" aria-label="Thanh menu chính"><div className="side-menu-brand">{appSettings.softwareName}</div><button type="button" className="side-menu-close" onClick={()=>setMenuOpen(false)}>‹</button><nav>{MODULES.map(m=><button type="button" key={m.key} className={active===m.key?'active':''} onClick={()=>{openModule(m.key);setMenuOpen(true)}}><span>{m.number}</span>{m.label}</button>)}<button type="button" className={active==='staff'?'active':''} onClick={()=>{openModule('staff');setMenuOpen(true)}}><span>{STAFF_MODULE.number}</span>{STAFF_MODULE.label}</button></nav></aside>{!menuOpen&&<button type="button" className="side-menu-open" aria-label="Mở thanh menu" onClick={()=>setMenuOpen(true)}>›</button>}<div className="app-main"><div className={'connection '+(health?.ok&&health?.supabaseDatabaseReachable?'connected':'')}>{health===null?'Đang kiểm tra kết nối...':health?.ok&&health?.supabaseDatabaseReachable?'Vercel + Supabase: ĐÃ KẾT NỐI':'Kiểm tra lại cấu hình Supabase'}</div>{active===null?<HomeScreen alerts={homeAlerts} staff={homeStaff} onOpen={openModule} onOpenAlert={openAlert} onFilterManager={filterAlertManager} onRefreshAlerts={()=>void loadHomeAlerts()}/>:<ModuleScreen module={active} payload={payload} loading={loading} error={error} filters={filters} managerFilter={filters.manager} setFilter={setFilter} departments={departments} staffNames={staffNames} onReset={resetFilters} onCreate={()=>openCreate(active)} onCreateChecklist={(formCode?:string)=>openCreate('checklists',formCode?{formCode}: {})} onCreateReminder={()=>openCreate('reminders')} onCreateError={()=>openCreate('violationError')} onCreateForm={()=>openCreate('checklistForm')} onCreateCriterion={()=>openCreate('checklistCriterion')} onCreateFeedback={()=>openCreate('feedback')} onCreateRule={()=>openCreate('rule')} onEdit={(row:AnyRecord)=>openEdit((row.__module||active) as FormModule,row)} onRemove={(row:AnyRecord)=>remove((row.__module||active) as FormModule,row)} onPlanAction={planAction} onInline={inlineUpdate} onOpenAlert={openAlert} onFilterManager={filterAlertManager} onBack={()=>setActive(null)} onToggleDaily={(row,daily)=>toggleReminder(row,daily)} onReload={()=>setRefresh(x=>x+1)}/>} {modal&&<EditModal module={modal.module as FormModule} form={form} payload={payload} departments={departments} change={change} error={modalError} onClose={()=>{if(!formIsSaving(form)){setModalError('');setModal(null)}}} onDismissError={()=>setModalError('')} onSave={save} onLeaveEdit={editLeaveEntry} onLeaveRemove={removeLeaveEntry}/>}</div></div>;
}

function NotificationMessagePanel({rows,onOpenAlert}:{rows:AnyRecord[];onOpenAlert:(alert:AnyRecord)=>void}){
 const safeRows=useMemo(()=>recordArray(rows),[rows]);
 const messages=useMemo(()=>safeRows.filter(x=>x.notificationAudience==='EMPLOYEE'||['CÔNG VIỆC MỚI GIAO','PHẢN HỒI','Ý KIẾN QUẢN LÝ','NHẮC VIỆC','NHẮC VIỆC HÀNG NGÀY','TỒN TẠI / KIẾN NGHỊ','BẢNG KIỂM CẦN XỬ LÝ'].includes(text(x.kind))).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,12),[safeRows]);
 const label=(item:AnyRecord)=>item.kind==='CÔNG VIỆC MỚI GIAO'?'VIỆC MỚI':item.kind==='PHẢN HỒI'?'TRƯỞNG KHOA/QUẢN LÝ PHẢN HỒI':item.kind==='NHẮC VIỆC HÀNG NGÀY'?'NHẮC HÀNG NGÀY':item.kind==='NHẮC VIỆC'?'NHẮC VIỆC':item.kind||'THÔNG BÁO';
 return <section className="employee-notifications"><div className="employee-notifications-heading"><div><div className="section-title">💬 THÔNG BÁO CHO NHÂN VIÊN</div><p>Việc mới, nhắc việc và phản hồi của quản lý được hiển thị như tin nhắn. Nhấn vào tin nhắn để mở đúng phân hệ.</p></div><span>{messages.length} tin nhắn</span></div>{messages.length?<div className="notification-message-list">{messages.map((item,index)=><article className="notification-message-item" key={(item.row_no||item.id||index)+'-'+(item.notificationType||item.kind)}><button type="button" className={'notification-message '+alertVisualClass(item)} onClick={()=>onOpenAlert(item)}><div className="notification-message-head"><b>{label(item)}</b><Badge value={item.approvalStatus||item.level}/></div><strong>{item.notificationTitle||item.title||'Thông báo công việc'}</strong><p>{item.message||item.approvalResponse||item.managerOpinion||item.instruction||'Mở chi tiết để xem nội dung.'}</p><small>{[item.person,item.managerName,item.department].filter(Boolean).join(' · ')||'Toàn bộ nhân sự'} · {formatDate(item.date)}</small><em>Nhấn để mở chi tiết</em></button></article>)}</div>:<div className="empty compact">Chưa có thông báo cần xử lý.</div>}</section>;
}

function HomeScreen({alerts,staff,onOpen,onOpenAlert,onFilterManager,onRefreshAlerts}:{alerts:AnyRecord[];staff:AnyRecord[];onOpen:(key:MainModule)=>void;onOpenAlert:(alert:AnyRecord)=>void;onFilterManager:(managerName:string)=>void;onRefreshAlerts:()=>void}){
 const cleanAlerts=useMemo(()=>recordArray(alerts).filter(x=>!isViolationAlert(x)),[alerts]);
 const cleanStaff=useMemo(()=>recordArray(staff),[staff]);
 const[personFilter,setPersonFilter]=useState('');
 const pickerStaff=useMemo(()=>{const merged=[...cleanStaff,...cleanAlerts.filter(x=>x.person).map(x=>({name:x.person,department:x.department||''})),...cleanAlerts.filter(x=>x.managerName).map(x=>({name:x.managerName,department:x.department||''}))];const unique=new Map<string,AnyRecord>();for(const item of merged){const key=normalize(item.name);if(key&&!unique.has(key))unique.set(key,item);}return [...unique.values()];},[cleanStaff,cleanAlerts]);
 const visibleAlerts=useMemo(()=>cleanAlerts.filter(x=>!personFilter||sameValue(x.person,personFilter)||sameValue(x.managerName,personFilter)),[cleanAlerts,personFilter]);
 return <main className="content-shell"><section className="home-alerts home-alerts-first"><div className="home-alerts-heading"><div><div className="section-title">⚠ CẢNH BÁO CẦN XỬ LÝ</div><p>Hiển thị cảnh báo quá hạn, việc hôm nay và nội dung cần xử lý của tất cả các phân hệ.</p></div><div className="home-alert-heading-actions"><button type="button" className="alert-open-all" onClick={()=>onOpen('alerts')}>XEM TẤT CẢ CẢNH BÁO</button><button type="button" className="edit-btn" onClick={onRefreshAlerts}>↻ CẬP NHẬT CẢNH BÁO</button></div></div><div className="home-alert-filter-bar"><div><b>Lọc cảnh báo theo nhân viên</b><small>Gõ tên → lọc → chọn để xem toàn bộ cảnh báo của người đó.</small></div><SmartStaffPicker staff={pickerStaff} value={personFilter} onChange={setPersonFilter} showPosition placeholder="Gõ tên nhân viên → lọc → chọn"/>{personFilter&&<button type="button" className="filter-clear" onClick={()=>setPersonFilter('')}>XÓA LỌC</button>}</div>{visibleAlerts.length?<div className="alert-strip">{visibleAlerts.slice(0,8).map((a,i)=><article className={'home-alert-item '+alertVisualClass(a)} key={(a.row_no||a.id||i)+'-'+a.kind}><button type="button" className="home-alert-card" onClick={()=>onOpenAlert(a)}><b>{a.level}</b><span>{a.notificationTitle||a.title||a.kind}</span>{a.message&&<em className="home-alert-detail">{a.message}</em>}{a.instruction&&<em className="home-alert-detail alert-instruction">Việc cần làm: {a.instruction}</em>}{approvalActionForAlert(a)&&<ApprovalSteps status={a.approvalStatus} action={approvalActionForAlert(a)} compact/>}{(a.managerOpinion||a.approvalResponse||a.approvalRequest)&&<em className="home-alert-detail">{a.managerOpinion||a.approvalResponse||a.approvalRequest}</em>}<small>{[a.person,a.managerName,a.department].filter(Boolean).join(' · ')} · {formatDate(a.date)}</small></button></article>)}</div>:<div className="empty compact">Không có cảnh báo phù hợp với nhân viên đã chọn.</div>}<NotificationMessagePanel rows={visibleAlerts} onOpenAlert={onOpenAlert}/><div className="home-alert-table"><div className="home-alert-table-heading"><div><b>CẢNH BÁO QUÁ HẠN VÀ VIỆC HÔM NAY CỦA TẤT CẢ CÁC MỤC</b><small>{personFilter?'Đang lọc: '+personFilter:'Tổng thể toàn bộ nhân sự và các phân hệ'}</small></div><span>{visibleAlerts.length} cảnh báo</span></div><AlertTable rows={visibleAlerts} onOpenAlert={onOpenAlert} onFilterManager={onFilterManager}/></div></section></main>;
}

function FilterBar({module,filters,setFilter,departments,staffNames,staff,managerStaff,onReset,onReload}:{module:MainModule;filters:AnyRecord;setFilter:(key:string,value:any)=>void;departments:string[];staffNames:string[];staff:AnyRecord[];managerStaff:AnyRecord[];onReset:()=>void;onReload:()=>void}){
 const dates=['tasks','violations','checklists','plans','reports','kpi'].includes(module);
 const taskStaffObjects=staff.filter(x=>!filters.department||normalize(x.department)===normalize(filters.department));
 const taskStaff=taskStaffObjects.map(x=>x.name).filter(Boolean);
 const taskStaffNames=taskStaff.length?taskStaff:staffNames;
 return <form className="module-filters" onSubmit={e=>{e.preventDefault();onReload();}}>
  {dates&&<><label>Từ ngày<input type="date" value={filters.from||''} onChange={e=>setFilter('from',e.target.value)}/></label><label>Đến ngày<input type="date" value={filters.to||''} onChange={e=>setFilter('to',e.target.value)}/></label></>}
  {['staff','tasks','violations','checklists','plans','reports','kpi','alerts'].includes(module)&&<label>Bộ phận<select value={filters.department||''} onChange={e=>setFilter('department',e.target.value)}><option value="">Tất cả bộ phận</option>{departments.map(x=><option key={x}>{x}</option>)}</select></label>}
  {['violations','checklists','plans','reports'].includes(module)&&<label className="filter-wide">Nhân viên<SmartStaffPicker staff={taskStaffObjects.length?taskStaffObjects:staff} value={filters.person||''} onChange={x=>setFilter('person',x)} placeholder="Gõ tên hoặc mã → lọc → chọn" showPosition/></label>}
  {module==='alerts'&&<label className="filter-wide">Tên nhân viên / quản lý được cảnh báo<SmartStaffPicker staff={staff} value={filters.manager||filters.person} onChange={x=>{const selected=staff.find(y=>sameValue(y.name,x));if(selected?.isManager){setFilter('manager',x);setFilter('person','');setFilter('approvalStatus','')}else{setFilter('person',x);setFilter('manager','');}}} showPosition placeholder="Gõ tên → lọc → chọn; kết quả hiện cả Chức vụ"/></label>}
  {['staff','kpi'].includes(module)&&<label className="filter-wide">Tìm nhân viên<SmartStaffPicker staff={taskStaffObjects.length?taskStaffObjects:staff} value={filters.person||''} onChange={x=>setFilter('person',x)} placeholder="Gõ tên hoặc mã → lọc → chọn" showPosition/></label>}
  {module==='tasks'&&<><label className="filter-wide">Tên người thực hiện<SmartStaffPicker staff={taskStaffObjects.length?taskStaffObjects:staff} value={filters.person||''} onChange={x=>setFilter('person',x)} placeholder="Gõ tên → lọc → chọn" showPosition/></label><label className="filter-wide">Tìm tiêu đề<input placeholder="Nhập tên tiêu đề..." value={filters.title||''} onChange={e=>setFilter('title',e.target.value)}/></label><label>Mức ưu tiên<select value={filters.priority||''} onChange={e=>setFilter('priority',e.target.value)}><option value="">Tất cả ưu tiên</option>{(filters.optionsPriorities||[]).map((x:string)=><option key={x}>{x}</option>)}</select></label><SmartMulti options={taskStaffNames} value={filters.assignees||[]} onChange={x=>setFilter('assignees',x)} placeholder="Nhiều người thực hiện"/><SmartMulti options={filters.optionsStatuses||[]} value={filters.statuses||[]} onChange={x=>setFilter('statuses',x)} placeholder="Nhiều trạng thái"/><label>Danh mục phê duyệt<select value={filters.approvalStatus||''} onChange={e=>setFilter('approvalStatus',e.target.value)}><option value="">Tất cả phê duyệt</option>{(filters.optionsApprovalStatuses||[]).map((x:string)=><option key={x} value={x}>{approvalLabel(x)}</option>)}</select></label><label className="filter-wide">Quản lý phê duyệt<SmartStaffPicker staff={managerStaff} value={filters.manager} onChange={x=>setFilter('manager',x)} placeholder="Gõ tên quản lý theo Chức vụ → chọn"/></label></>}
  {module==='alerts'&&<label>Trạng thái phê duyệt<select value={filters.approvalStatus||''} onChange={e=>setFilter('approvalStatus',e.target.value)}><option value="">Tất cả trạng thái</option>{(filters.optionsApprovalStatuses||[]).map((x:string)=><option key={x} value={x}>{approvalLabel(x)}</option>)}</select></label>}
  
  {module==='checklists'&&<label>Phiếu giám sát<select value={filters.formCode||''} onChange={e=>setFilter('formCode',e.target.value)}><option value="">Tất cả phiếu</option>{(filters.optionsForms||[]).map((x:AnyRecord)=><option value={x.code} key={x.code}>{x.code} - {x.name}</option>)}</select></label>}
  {module==='plans'&&<><label>Loại kế hoạch<select value={filters.type||'TUẦN'} onChange={e=>setFilter('type',e.target.value)}><option>TUẦN</option><option>THÁNG</option></select></label><label>Trạng thái<select value={filters.status||''} onChange={e=>setFilter('status',e.target.value)}><option value="">Tất cả trạng thái</option>{(filters.optionsPlanStatuses||[]).map((x:string)=><option key={x}>{x}</option>)}</select></label></>}
  {module==='reports'&&<ReportSectionPicker value={Array.isArray(filters.reportSection)?filters.reportSection:REPORT_SECTION_IDS} onChange={x=>setFilter('reportSection',x)}/>}
  <button className="filter-submit">{module==='kpi'?'TÍNH KPI':'TÌM KIẾM'}</button><button type="button" className="filter-reset" onClick={onReset}>XÓA BỘ LỌC</button>
 </form>;
}

function ModuleScreen({module,payload,loading,error,filters,managerFilter,setFilter,departments,staffNames,onReset,onCreate,onCreateChecklist,onCreateReminder,onCreateError,onCreateForm,onCreateCriterion,onCreateFeedback,onCreateRule,onEdit,onRemove,onPlanAction,onInline,onOpenAlert,onFilterManager,onBack,onToggleDaily,onReload}:{module:MainModule;payload:AnyRecord;loading:boolean;error:string;filters:AnyRecord;managerFilter?:string;setFilter:(key:string,value:any)=>void;departments:string[];staffNames:string[];onReset:()=>void;onCreate:()=>void;onCreateChecklist:(formCode?:string)=>void;onCreateReminder:()=>void;onCreateError:()=>void;onCreateForm:()=>void;onCreateCriterion:()=>void;onCreateFeedback:()=>void;onCreateRule:()=>void;onEdit:(row:AnyRecord)=>void;onRemove:(row:AnyRecord)=>void;onPlanAction:(op:string,row:AnyRecord)=>void;onInline:(body:AnyRecord)=>void;onOpenAlert:(alert:AnyRecord)=>void;onFilterManager:(managerName:string)=>void;onBack:()=>void;onToggleDaily:(row:AnyRecord,daily:boolean)=>void;onReload:()=>void}){
 if(module==='settings')return <main><div className="module-toolbar"><button className="back-btn" onClick={onBack}>← TRANG CHỦ</button><h2>CÀI ĐẶT HỆ THỐNG</h2></div><section className="content-shell"><div className="panel-card"><PasswordSettings/></div></section></main>;
 const title=MODULE_LABELS[module]||module;const filterPayload={...filters,optionsPriorities:payload.options?.priorities||[],optionsStatuses:payload.options?.statuses||[],optionsApprovalStatuses:payload.options?.approvalStatuses||[],optionsViolationStatuses:payload.options?.violationStatuses||[],optionsForms:payload.forms||[],optionsPlanStatuses:payload.options?.statuses||[]};const filterPendingApproval=()=>{setFilter('from','');setFilter('to','');setFilter('approvalStatus','CHỜ PHÊ DUYỆT');};return <main><div className="module-toolbar"><button className="back-btn" onClick={onBack}>← TRANG CHỦ</button><h2>{title}</h2></div><section className="content-shell"><FilterBar module={module} filters={filterPayload} setFilter={setFilter} departments={departments} staffNames={staffNames} staff={(payload.staff||[]) as AnyRecord[]} managerStaff={(payload.managerStaff||[]) as AnyRecord[]} onReset={onReset} onReload={onReload}/>{error&&<div className="error-box">{error}</div>}{loading?<div className="panel-card"><p>Đang tải dữ liệu...</p></div>:<View module={module} payload={payload} filters={filters} managerFilter={managerFilter} onCreate={onCreate} onCreateChecklist={onCreateChecklist} onCreateReminder={onCreateReminder} onCreateError={onCreateError} onCreateForm={onCreateForm} onCreateCriterion={onCreateCriterion} onCreateFeedback={onCreateFeedback} onCreateRule={onCreateRule} onEdit={onEdit} onRemove={onRemove} onPlanAction={onPlanAction} onInline={onInline} onOpenAlert={onOpenAlert} onFilterManager={onFilterManager} onFilterApproval={filterPendingApproval} onToggleDaily={onToggleDaily} onReload={onReload}/>}</section></main>;
}

function ChecklistReview({row,details,onClose}:{row:AnyRecord;details:AnyRecord[];onClose:()=>void}){
 const formDetails=details.filter(x=>sameValue(x.formId,row.id));
 return <div className="panel-card checklist-review-panel"><div className="toolbar-line"><div><h3>XEM LẠI PHIẾU GIÁM SÁT</h3><p className="muted">Toàn bộ nội dung của phiếu đã chọn, không thay đổi dữ liệu.</p></div><button type="button" className="filter-reset" onClick={onClose}>ĐÓNG</button></div><div className="checklist-review-meta"><div><small>Ngày giám sát</small><b>{formatDate(row.date)}</b></div><div><small>Phiếu</small><b>{row.formCode||'—'} · {row.formName||'—'}</b></div><div><small>Nhân viên</small><b>{row.person||'—'} {row.staffId?`(${row.staffId})`:''}</b></div><div><small>Bộ phận</small><b>{row.department||'—'}</b></div><div><small>Người giám sát</small><b>{row.supervisor||'—'}</b></div><div><small>Khu vực / Ca</small><b>{[row.area,row.shift].filter(Boolean).join(' · ')||'—'}</b></div><div><small>Tỷ lệ / Xếp loại</small><b>{row.percentRate??row.rate??0}% · {row.percentRank||'—'}</b></div><div><small>Điểm KPI</small><b>{row.percentKpi??row.kpi??0}</b></div></div><div className="checklist-review-note"><b>Ghi chú chung:</b> {row.note||'—'}<span className="checklist-review-evidence"><b>Ảnh:</b> <ReportEvidence value={row.imageName} legacyId={row.id} kind="image" emptyLabel="Chưa có"/> <b>Tài liệu:</b> <ReportEvidence value={row.documentName} legacyId={row.id} kind="document" emptyLabel="Chưa có"/></span></div><div className="table-wrap checklist-review-table"><table><thead><tr><th>STT</th><th>Nhóm</th><th>Nội dung</th><th>Nội dung chi tiết</th><th>Kết quả</th><th>Ghi chú</th><th>Ảnh lỗi</th><th>Ảnh khắc phục</th></tr></thead><tbody>{formDetails.length?formDetails.sort((a,b)=>Number(a.order||0)-Number(b.order||0)).map((item,index)=><tr key={item.row_no||item.criterionId||index}><td>{item.order||index+1}</td><td>{item.group||'—'}</td><td>{item.content||'—'}</td><td>{item.detail||'—'}</td><td><Badge value={item.result}/></td><td>{item.note||'—'}</td><td><ReportEvidence value={item.imageRef} legacyId={`${row.id}:${item.criterionId||'criterion'}`} kind="image" emptyLabel="Chưa có"/></td><td><ReportEvidence value={item.correctiveImageRef} legacyId={`${row.id}:${item.criterionId||'criterion'}:fix`} kind="image" emptyLabel="Chưa có"/></td></tr>):<tr><td colSpan={8} className="empty-cell">Không tìm thấy chi tiết của phiếu này.</td></tr>}</tbody></table></div></div>;
}

function sameValue(a:any,b:any){return normalize(a)===normalize(b);}

function ChecklistFormDetail({form,criteria,onClose,onUse}:{form:AnyRecord;criteria:AnyRecord[];onClose:()=>void;onUse:()=>void}){
 const formCode=text(form.code);const items=criteria.filter(x=>sameValue(x.formCode,formCode)).sort((a,b)=>Number(a.order||0)-Number(b.order||0));
 return <div className="panel-card checklist-definition-detail"><div className="toolbar-line"><div><h3>CHI TIẾT MẪU PHIẾU</h3><p className="muted">Đang mở theo mã phiếu: <b>{formCode||'—'}</b>. Chi tiết chỉ xuất hiện sau khi chọn một mẫu.</p></div><div className="card-actions"><button type="button" className="add-btn" onClick={onUse}>CHỌN PHIẾU NÀY ĐỂ CHẤM</button><button type="button" className="filter-reset" onClick={onClose}>ĐÓNG CHI TIẾT</button></div></div><div className="checklist-definition-meta"><div><small>Mã phiếu</small><b>{formCode||'—'}</b></div><div><small>Tên phiếu</small><b>{form.name||'—'}</b></div><div><small>Bộ phận</small><b>{form.department||'—'}</b></div><div><small>Số tiêu chí</small><b>{items.length||form.criteriaCount||0}</b></div><div className="wide"><small>Mô tả</small><b>{form.description||'—'}</b></div><div><small>Trạng thái</small><Badge value={form.status||'Hoạt động'}/></div></div><div className="table-wrap checklist-definition-table"><table><thead><tr><th>STT</th><th>NHÓM</th><th>NỘI DUNG</th><th>NỘI DUNG CHI TIẾT</th><th>CHO PHÉP ẢNH</th><th>TRẠNG THÁI</th></tr></thead><tbody>{items.length?items.map((item,index)=><tr key={item.row_no||item.id||index}><td>{item.order||index+1}</td><td>{item.group||'—'}</td><td>{item.content||'—'}</td><td>{item.detail||'—'}</td><td>{item.allowImage||'Có'}</td><td><Badge value={item.status||'Hoạt động'}/></td></tr>):<tr><td colSpan={6} className="empty-cell">Mẫu phiếu này chưa có tiêu chí trong DM_BANGKIEM.</td></tr>}</tbody></table></div></div>;
}

function ChecklistFormEditDetail({form,criteria,departments,onClose,onSaved}:{form:AnyRecord;criteria:AnyRecord[];departments:string[];onClose:()=>void;onSaved:()=>void}){
 const [draft,setDraft]=useState<AnyRecord>({...form});
 const [items,setItems]=useState<AnyRecord[]>(()=>criteria.filter(x=>sameValue(x.formCode,form.code)).sort((a,b)=>Number(a.order||0)-Number(b.order||0)).map(x=>({...x})));
 const [saving,setSaving]=useState(false);const [error,setError]=useState('');
 const changeItem=(index:number,key:string,value:any)=>setItems(current=>current.map((item,position)=>position===index?{...item,[key]:value}:item));
 const addItem=()=>setItems(current=>[...current,{id:`BK${Date.now()}${current.length}`,formCode:draft.code,department:draft.department,group:'Chung',order:current.length+1,content:'',detail:'',allowImage:'Có',status:'Hoạt động'}]);
 async function save(){
  if(!text(draft.code)||!text(draft.name)){setError('Mã phiếu và tên phiếu không được để trống.');return;}
  if(items.some(item=>!text(item.content))){setError('Mỗi tiêu chí phải có nội dung.');return;}
  setSaving(true);setError('');
  try{
   const formResponse=await fetch('/api/modules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:'checklistForm',op:'save',row_no:form.row_no,code:draft.code,name:draft.name,department:draft.department,description:draft.description,status:draft.status})});
   const formResult=await formResponse.json();if(!formResponse.ok||!formResult.ok)throw new Error(formResult.error||'Không lưu được thông tin mẫu phiếu.');
   for(const [index,item] of items.entries()){
    const response=await fetch('/api/modules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:'checklistCriterion',op:'save',row_no:item.row_no,id:item.id||`BK${Date.now()}${index}`,formCode:draft.code,department:draft.department,group:item.group,content:item.content,detail:item.detail,order:item.order||index+1,allowImage:item.allowImage||'Có',status:item.status||'Hoạt động'})});
    const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||`Không lưu được tiêu chí số ${index+1}.`);
   }
   onSaved();
  }catch(error){setError(error instanceof Error?error.message:'Không lưu được mẫu phiếu.');}finally{setSaving(false);}
 }
 return <div className="panel-card checklist-definition-editor"><div className="toolbar-line"><div><h3>{form.row_no?'SỬA':'TẠO'} CHI TIẾT PHIẾU GIÁM SÁT</h3><p className="muted">{form.row_no?'Mã phiếu là khóa liên kết với lịch sử chấm, vì vậy không đổi mã khi đã có dữ liệu.':'Nhập thông tin mẫu phiếu rồi thêm toàn bộ tiêu chí ngay trong màn hình chi tiết này.'}</p></div><div className="card-actions"><button type="button" className="filter-reset" onClick={onClose} disabled={saving}>ĐÓNG</button><button type="button" className="save-btn" onClick={save} disabled={saving}>{saving?'ĐANG LƯU...':'LƯU PHIẾU VÀ TIÊU CHÍ'}</button></div></div>{error&&<div className="error-box">{error}</div>}<div className="checklist-editor-fields"><label>Mã phiếu<input value={text(draft.code)} readOnly={Boolean(form.row_no)} onChange={e=>setDraft(x=>({...x,code:e.target.value}))} required/></label><label>Tên phiếu<input value={text(draft.name)} onChange={e=>setDraft(x=>({...x,name:e.target.value}))} required/></label><label>Bộ phận<select value={text(draft.department)} onChange={e=>setDraft(x=>({...x,department:e.target.value}))}><option value="">Chọn bộ phận</option>{departments.map(item=><option key={item}>{item}</option>)}</select></label><label>Trạng thái<select value={text(draft.status)||'Hoạt động'} onChange={e=>setDraft(x=>({...x,status:e.target.value}))}><option>Hoạt động</option><option>Tạm ngưng</option></select></label><label className="wide">Mô tả<textarea rows={3} value={text(draft.description)} onChange={e=>setDraft(x=>({...x,description:e.target.value}))}/></label></div><div className="toolbar-line checklist-editor-criteria-head"><div><h4>DANH SÁCH TIÊU CHÍ CHI TIẾT</h4><small>{items.length} tiêu chí · chỉnh sửa trực tiếp trên từng dòng</small></div><button type="button" className="edit-btn" onClick={addItem} disabled={saving}>+ THÊM TIÊU CHÍ</button></div><div className="table-wrap checklist-definition-editor-table"><table><thead><tr><th>STT</th><th>NHÓM</th><th>NỘI DUNG (*)</th><th>NỘI DUNG CHI TIẾT</th><th>CHO PHÉP ẢNH</th><th>TRẠNG THÁI</th></tr></thead><tbody>{items.length?items.map((item,index)=><tr key={item.row_no||item.id||index}><td><input type="number" value={item.order||index+1} onChange={e=>changeItem(index,'order',e.target.value)}/></td><td><input value={text(item.group)} onChange={e=>changeItem(index,'group',e.target.value)}/></td><td><textarea rows={3} value={text(item.content)} onChange={e=>changeItem(index,'content',e.target.value)} required/></td><td><textarea rows={3} value={text(item.detail)} onChange={e=>changeItem(index,'detail',e.target.value)}/></td><td><select value={text(item.allowImage)||'Có'} onChange={e=>changeItem(index,'allowImage',e.target.value)}><option>Có</option><option>Không</option></select></td><td><select value={text(item.status)||'Hoạt động'} onChange={e=>changeItem(index,'status',e.target.value)}><option>Hoạt động</option><option>Tạm ngưng</option></select></td></tr>):<tr><td colSpan={6} className="empty-cell">Chưa có tiêu chí. Bấm “+ THÊM TIÊU CHÍ” để tạo.</td></tr>}</tbody></table></div></div>;
}

function ChecklistFormCatalog({forms,onSelect,onEdit,onRemove}:{forms:AnyRecord[];onSelect:(form:AnyRecord)=>void;onEdit:(form:AnyRecord)=>void;onRemove:(form:AnyRecord)=>void}){
 return <div className="panel-card"><div className="toolbar-line"><div><h3>DANH MỤC MẪU PHIẾU</h3><p className="muted">Bấm vào <b>mã phiếu</b> hoặc <b>tên phiếu</b> để mở nội dung chi tiết. Mã phiếu là khóa nhận diện nên vẫn chọn đúng khi tên phiếu trùng.</p></div><b>{forms.length} mẫu</b></div><div className="table-wrap checklist-form-catalog"><table><thead><tr><th>STT</th><th>MÃ PHIẾU</th><th>TÊN PHIẾU</th><th>BỘ PHẬN</th><th>SỐ TIÊU CHÍ</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody>{forms.length?forms.map((form,index)=><tr key={`${form.code||'form'}-${form.row_no||form.legacy_id||index}`}><td>{index+1}</td><td><button type="button" className="checklist-link-button" onClick={()=>onSelect(form)}>{form.code||'—'}</button></td><td><button type="button" className="checklist-link-button checklist-form-name" onClick={()=>onSelect(form)}>{form.name||'—'}</button></td><td>{form.department||'—'}</td><td>{form.criteriaCount||0}</td><td><Badge value={form.status||'Hoạt động'}/></td><td className="actions-cell"><button type="button" className="edit-btn" onClick={()=>onSelect(form)}>XEM CHI TIẾT</button><button type="button" className="edit-btn" onClick={()=>onEdit({...form,__module:'checklistForm'})}>SỬA</button><button type="button" className="danger" onClick={()=>onRemove({...form,__module:'checklistForm'})}>XÓA</button></td></tr>):<tr><td colSpan={7} className="empty-cell">Chưa có mẫu phiếu trong DM_PHIEU_GIAMSAT.</td></tr>}</tbody></table></div></div>;
}

function ChecklistRunStart({forms,criteria,selectedFormCode,onSelect,onCreate}:{forms:AnyRecord[];criteria:AnyRecord[];selectedFormCode:string;onSelect:(code:string)=>void;onCreate:(formCode?:string)=>void}){
 const selected=forms.find(x=>sameValue(x.code,selectedFormCode));
 return <div className="panel-card checklist-run-start"><div className="toolbar-line"><div><h3>BẢNG KIỂM GIÁM SÁT</h3><p className="muted">Chọn mã phiếu để xem đúng bộ tiêu chí, sau đó mở phiếu để chấm theo cấu trúc Script.</p></div><button type="button" className="add-btn" onClick={()=>onCreate(selectedFormCode||undefined)}>+ CHẤM PHIẾU GIÁM SÁT</button></div><div className="checklist-run-select"><label>Phiếu giám sát<select value={selectedFormCode} onChange={e=>onSelect(e.target.value)}><option value="">-- Chọn mã phiếu --</option>{forms.map((form,index)=><option key={`${form.code||'form'}-${form.row_no||index}`} value={form.code||''}>{form.code||'—'} - {form.name||'Chưa có tên'}</option>)}</select></label>{selected&&<div className="checklist-selected-form"><small>Đang chọn</small><b>{selected.code} · {selected.name}</b><span>{selected.department||'Chưa có bộ phận'} · {selected.criteriaCount||0} tiêu chí</span></div>}</div>{selected&&<ChecklistFormDetail form={selected} criteria={criteria} onClose={()=>onSelect('')} onUse={()=>onCreate(selected.code)}/>}</div>;
}

function ScriptChecklistView({payload,onCreateChecklist,onCreateForm,onCreateCriterion,onEdit,onRemove,onReload}:{payload:AnyRecord;onCreateChecklist:(formCode?:string)=>void;onCreateForm:()=>void;onCreateCriterion:()=>void;onEdit:(row:AnyRecord)=>void;onRemove:(row:AnyRecord)=>void;onReload:()=>void}){
 const summary=payload.summary||{},history=(payload.rows||[]) as AnyRecord[],configs=(payload.percentConfig||payload.scoring||[]) as AnyRecord[],details=(payload.details||[]) as AnyRecord[],forms=(payload.forms||[]) as AnyRecord[],criteria=(payload.criteria||[]) as AnyRecord[];
 const[selectedId,setSelectedId]=useState('');const[selectedFormCode,setSelectedFormCode]=useState('');const[editingForm,setEditingForm]=useState<AnyRecord|null>(null);const[creatingForm,setCreatingForm]=useState<AnyRecord|null>(null);const[tab,setTab]=useState<'run'|'create'|'history'>('run');
 const selected=selectedId?history.find(row=>sameValue(row.id,selectedId)||sameValue(row.legacy_id,selectedId)||sameValue(row.row_no,selectedId))||null:null;
 const selectedForm=selectedFormCode?forms.find(form=>sameValue(form.code,selectedFormCode))||null:null;
 const showTab=(next:'run'|'create'|'history')=>{setTab(next);if(next!=='history')setSelectedId('');};
 return <div className="module-stack">
  <div className="summary-cards"><div><b>{summary.total||0}</b><span>Phiếu đã lưu</span></div><div><b>{summary.applied||0}</b><span>Tiêu chí áp dụng</span></div><div><b>{summary.pass||0}</b><span>Đạt</span></div><div><b>{summary.fail||0}</b><span>Không đạt</span></div><div><b>{summary.na||0}</b><span>Không áp dụng</span></div><div><b>{summary.averagePercentRate??summary.averageRate??0}%</b><span>Tỷ lệ đạt bình quân</span></div></div>
  <div className="checklist-tabs" role="tablist" aria-label="Khu vực bảng kiểm"><button type="button" role="tab" aria-selected={tab==='run'} className={tab==='run'?'active':''} onClick={()=>showTab('run')}>✓ CHẤM PHIẾU GIÁM SÁT</button><button type="button" role="tab" aria-selected={tab==='create'} className={tab==='create'?'active':''} onClick={()=>showTab('create')}>＋ TẠO / SỬA PHIẾU GIÁM SÁT</button><button type="button" role="tab" aria-selected={tab==='history'} className={tab==='history'?'active':''} onClick={()=>showTab('history')}>LỊCH SỬ PHIẾU GIÁM SÁT</button></div>
  {tab==='run'&&<><ChecklistRunStart forms={forms} criteria={criteria} selectedFormCode={selectedFormCode} onSelect={setSelectedFormCode} onCreate={onCreateChecklist}/><div className="panel-card checklist-run-note"><b>Luồng chấm phiếu:</b> chọn một mã phiếu ở trên hoặc vào tab <b>TẠO / SỬA PHIẾU GIÁM SÁT</b> để mở danh mục mẫu. Nội dung chi tiết không hiển thị cố định khi chưa chọn mẫu.</div></>}
  {tab==='create'&&<><div className="panel-card toolbar-line"><div><b>ĐÚNG CẤU TRÚC SCRIPT — QUẢN LÝ MẪU PHIẾU VÀ TIÊU CHÍ</b><p className="muted">Tạo hoặc sửa mẫu phiếu trong cùng màn hình chi tiết; tiêu chí được thêm trực tiếp bằng nút “+ THÊM TIÊU CHÍ”.</p></div><div className="card-actions"><button className="add-btn" onClick={()=>setCreatingForm({code:'',name:'',department:'',description:'',status:'Hoạt động'})}>+ THÊM MẪU PHIẾU</button><button className="edit-btn" onClick={onCreateCriterion}>+ THÊM TIÊU CHÍ</button></div></div>{creatingForm&&<ChecklistFormEditDetail form={creatingForm} criteria={[]} departments={[...new Set([...BASE_DEPARTMENTS,...(payload.departments||[])])].filter(Boolean).sort((a:string,b:string)=>a.localeCompare(b,'vi'))} onClose={()=>setCreatingForm(null)} onSaved={()=>{setCreatingForm(null);onReload();}}/>}<div className="panel-card"><h3>CẤU HÌNH CHẤM ĐIỂM / KPI THEO PHIẾU</h3><DataTable rows={configs} columns={['formCode','thresholdA','thresholdB','thresholdC','labelA','labelB','labelC','labelBelow','useCustomKpi','kpiBands','kpiBelow']} headers={['Mã phiếu','Ngưỡng A','Ngưỡng B','Ngưỡng C','Mức A','Mức B','Mức C','Dưới C','KPI riêng','Các mức KPI','KPI dưới ngưỡng']}/></div><ChecklistFormCatalog forms={forms} onSelect={form=>setSelectedFormCode(text(form.code))} onEdit={form=>{setCreatingForm(null);setEditingForm(form)}} onRemove={onRemove}/>{selectedForm&&<ChecklistFormDetail form={selectedForm} criteria={criteria} onClose={()=>setSelectedFormCode('')} onUse={()=>setTab('run')}/>} {editingForm&&<ChecklistFormEditDetail form={editingForm} criteria={criteria} departments={[...new Set([...BASE_DEPARTMENTS,...(payload.departments||[])])].filter(Boolean).sort((a:string,b:string)=>a.localeCompare(b,'vi'))} onClose={()=>setEditingForm(null)} onSaved={()=>{setEditingForm(null);onReload();}}/>}</>}
  {tab==='history'&&<><div className="panel-card"><div className="toolbar-line"><div><h3>LỊCH SỬ PHIẾU GIÁM SÁT</h3><p className="muted">Đã lọc theo ngày, bộ phận, nhân viên và mã phiếu ở thanh lọc phía trên. Bấm “XEM CHI TIẾT” để xem một phiếu hoàn chỉnh.</p></div><b>{history.length} phiếu</b></div><DataTable rows={history} columns={['date','formCode','formName','person','department','supervisor','area','shift','applied','pass','fail','na','rate','percentRank','percentKpi','note']} headers={['Ngày','Mã phiếu','Tên phiếu','Nhân viên','Bộ phận','Giám sát','Khu vực','Ca','Áp dụng','Đạt','Không đạt','K.A.D','Tỷ lệ %','Xếp loại','KPI phiếu','Ghi chú']} actionRender={row=><div className="card-actions checklist-history-actions"><button type="button" className="edit-btn" onClick={()=>setSelectedId(String(row.id||row.legacy_id||row.row_no||''))}>XEM CHI TIẾT</button><button type="button" className="danger" onClick={()=>onRemove({...row,__module:'checklists'})}>XÓA PHIẾU GIÁM SÁT</button></div>}/></div>{selected&&<ChecklistReview row={selected} details={details} onClose={()=>setSelectedId('')}/>}</>}
 </div>;
}

function ReportErrorStatsTable({rows}:{rows:AnyRecord[]}){const data:AnyRecord[]=rows.map((row:AnyRecord,index):AnyRecord=>({...row,stt:index+1,alertLabel:row.alert?'Vượt ngưỡng cảnh báo':'Trong giới hạn'}));return <div className="table-wrap report-error-stats-wrap"><table className="report-error-stats-table"><thead><tr><th>STT</th><th>Tên lỗi phát hiện</th><th>Số lần ghi nhận</th><th>Trạng thái ngưỡng</th></tr></thead><tbody>{data.length?data.map((row:AnyRecord)=><tr key={`${row.errorName}-${row.stt}`}><td>{row.stt}</td><td>{row.errorName||'Lỗi chưa có mô tả'}</td><td className="report-error-count">{row.count||0}</td><td><span className={`report-alert-badge ${row.alert?'danger':'neutral'}`}>{row.alertLabel}</span></td></tr>):<tr><td colSpan={4} className="empty-cell">Không ghi nhận lỗi thường quy trong kỳ báo cáo.</td></tr>}</tbody></table></div>}
function ReportEvidence({value,legacyId,kind,emptyLabel}:{value?:any;legacyId?:any;kind:'image'|'document';emptyLabel:string}){const reference=text(value);if(/^https?:\/\//i.test(reference))return <a className="report-evidence-link" href={reference} target="_blank" rel="noreferrer">{kind==='image'?'🖼 XEM ẢNH':'📎 XEM TÀI LIỆU'}</a>;if(legacyId||reference)return <EvidenceLinks module="checklists" legacyId={legacyId} fallback={reference||undefined} kind={kind}/>;return <span className="report-evidence-empty">{emptyLabel}</span>}
function ReportErrorDetailTable({rows}:{rows:AnyRecord[]}){return <div className="table-wrap report-error-detail-wrap"><table className="report-error-detail-table"><thead><tr><th>TÊN NHÂN VIÊN</th><th>NỘI DUNG LỖI</th><th>HÌNH ẢNH GHI NHẬN</th><th>HÌNH ẢNH KHẮC PHỤC</th></tr></thead><tbody>{rows.length?rows.map((row,index)=>{const evidenceId=`${row.formId||row.formCode}:${row.criterionId||row.criterionCode||'criterion'}`;return <tr key={row.row_no||`${row.formId||row.formCode}-${index}`}><td><b>{row.name||'—'}</b><small className="report-error-sub">Khu vực: {row.area||'Chưa xác định'}</small><small className="report-error-sub">Ngày: {formatDate(row.date)}</small></td><td><div className="report-error-content">{row.errorName||row.detail||row.content||'Lỗi chưa có mô tả'}</div>{row.note&&<small className="report-error-sub">Ghi chú: {row.note}</small>}</td><td><ReportEvidence value={row.imageRef} legacyId={evidenceId} kind="image" emptyLabel="Chưa có ảnh ghi nhận"/></td><td><ReportEvidence value={row.correctiveImageRef} legacyId={`${evidenceId}:fix`} kind="image" emptyLabel="Chưa có ảnh khắc phục"/></td></tr>}):<tr><td colSpan={4} className="empty-cell">Không ghi nhận lỗi KHÔNG ĐẠT/KÉM trong kỳ báo cáo.</td></tr>}</tbody></table></div>}
function ReportMatrixMetrics({matrix}:{matrix:AnyRecord}){return <div className="report-matrix-metrics"><div><small>Số phiếu</small><b>{matrix.formCount||0}</b></div><div><small>Tiêu chí được đánh</small><b>{matrix.evaluated||0}</b></div><div><small>Đạt</small><b>{matrix.pass||0}</b></div><div><small>Không đạt/Kém</small><b>{matrix.fail||0}</b></div><div><small>Tỷ lệ đạt</small><b>{matrix.passRate||0}%</b></div></div>}
function ReportMatrixTable({matrix}:{matrix:AnyRecord}){const staff=(matrix.staff||[]) as AnyRecord[];const rows=(matrix.rows||[]) as AnyRecord[];return <div className="report-matrix-block"><div className="table-wrap report-matrix-wrap"><table className="report-matrix-table"><thead><tr><th>Tiêu chí đánh giá</th>{staff.map((person,index)=><th key={person.staffId||person.name||index}><b>{person.name||'Chưa ghi nhận'}</b><small>({person.area||person.areas?.join(' + ')||'Chưa ghi nhận'})</small></th>)}</tr></thead><tbody>{rows.length?rows.map((row,index)=><tr key={row.criterionId||index}><td><b className="matrix-criterion">{row.criterion||'Tiêu chí chưa có tên'}</b><small className="matrix-meta">{[row.formCode,row.group].filter(Boolean).join(' • ')}</small>{row.detail&&row.detail!==row.criterion&&<small className="matrix-detail">{row.detail}</small>}</td>{staff.map((person,personIndex)=>{const value=row.values?.[personIndex]||'';const normalized=normalize(value);return <td key={person.staffId||person.name||personIndex} className={normalized==='kem'?'matrix-poor':normalized==='khong dat'?'matrix-fail':''}>{value}</td>})}</tr>):<tr><td colSpan={Math.max(1,staff.length+1)} className="empty-cell">Chưa có tiêu chí phù hợp để dựng ma trận.</td></tr>}</tbody></table></div></div>}
function ReportMatrixStaffSummary({rows}:{rows:AnyRecord[]}){return <div className="table-wrap report-matrix-summary-wrap"><table className="report-matrix-summary"><thead><tr><th>TÊN NHÂN VIÊN</th><th>KHU VỰC</th><th>TỔNG TIÊU CHÍ ĐƯỢC ĐÁNH</th><th>SỐ TIÊU CHÍ ĐẠT</th><th>SỐ TIÊU CHÍ KHÔNG ĐẠT</th><th>SỐ TIÊU CHÍ KÉM</th><th>TỔNG LỖI</th><th>TỶ LỆ LỖI</th></tr></thead><tbody>{rows.length?rows.map((row,index)=><tr key={row.staffId||row.name||index}><td><b>{row.name||'—'}</b></td><td>{row.area||row.areas?.join(' + ')||'Chưa ghi nhận'}</td><td>{row.total??row.evaluated??0}</td><td className="text-ok">{row.pass||0}</td><td className="text-danger">{row.fail||0}</td><td className="text-danger">{row.poor||0}</td><td className="text-danger">{row.errors??row.fail??0}</td><td>{row.errorRate||0}%</td></tr>):<tr><td colSpan={8} className="empty-cell">Chưa có dữ liệu đánh giá.</td></tr>}</tbody></table></div>}
function reportOpinionFor(opinions:AnyRecord[],filters:AnyRecord,formCode=''){return opinions.find(item=>(!filters?.department||sameValue(item.department,filters.department))&&(!filters?.person||sameValue(item.person,filters.person))&&(!formCode||sameValue(item.formCode,formCode))&&(!filters?.from||!item.fromDate||sameValue(item.fromDate,filters.from))&&(!filters?.to||!item.toDate||sameValue(item.toDate,filters.to)))||null;}
function ReportOpinionEditor({opinions,filters,formCode='',formName='KẾT LUẬN TỔNG THỂ',onSave}:{opinions:AnyRecord[];filters:AnyRecord;formCode?:string;formName?:string;onSave:(body:AnyRecord)=>void}){const saved=reportOpinionFor(opinions,filters,formCode);const[value,setValue]=useState(text(saved?.opinion));const[state,setState]=useState('');useEffect(()=>{setValue(text(saved?.opinion));},[saved?.row_no,saved?.opinion]);const save=()=>{setState('Đang lưu...');onSave({kind:'OPINION',row_no:saved?.row_no,opinionId:saved?.opinionId||`YK-${formCode||'TONG-THE'}-${filters.from||'ALL'}-${filters.to||'ALL'}`,fromDate:filters.from,toDate:filters.to,department:filters.department,person:filters.person,formCode,formName,enteredBy:'Tổ trưởng',status:'Đã lưu',opinion:value});window.setTimeout(()=>setState('Đã tự động lưu'),250);};return <div className="report-opinion-box"><div className="report-opinion-heading"><div><b>✍ Ý KIẾN KHẮC PHỤC CỦA TỔ TRƯỞNG</b><small>{formName}{formCode?` · ${formCode}`:''}</small></div><span className={state.includes('lưu')?'saved':''}>{state|| (saved?.opinion?'Đã có nội dung lưu':'Chưa có nội dung')}</span></div><textarea value={value} onChange={e=>{setValue(e.target.value);setState('Chưa lưu thay đổi')}} onBlur={save} placeholder="Nhập ý kiến, nội dung khắc phục và đề xuất cải tiến..." rows={4}/><small className="report-autosave-hint">Rời khỏi ô nhập để tự động lưu vào Y_KIEN_BAO_CAO.</small></div>}
function reportExcelCell(value:any){return text(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function exportKpiExcel(rows:AnyRecord[],summary:AnyRecord,filePrefix='KPI_100_DIEM'){const columns=[['Mã NV','staffId'],['Họ tên','name'],['Bộ phận','department'],['Chức vụ','position'],['Điểm gốc','base'],['Điểm giao việc','taskScore'],['Điểm bảng kiểm','checklistScore'],['Điểm vi phạm','violationScore'],['Tổng điểm','total'],['Xếp loại','ranking'],['SL giao việc','taskCount'],['SL bảng kiểm','checkCount'],['SL vi phạm','violationCount'],['Chi tiết','details']];const head=columns.map(x=>`<th>${reportExcelCell(x[0])}</th>`).join('');const body=rows.map(row=>`<tr>${columns.map(([,key])=>`<td>${reportExcelCell(Array.isArray(row[key])?row[key].join(' | '):row[key])}</td>`).join('')}</tr>`).join('');const html=`<html><head><meta charset="utf-8"></head><body><h2>KPI 100 ĐIỂM</h2><p>Điểm bình quân: ${reportExcelCell(summary?.averageScore||0)}</p><table border="1"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></body></html>`;const blob=new Blob([`\ufeff${html}`],{type:'application/vnd.ms-excel;charset=utf-8'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`${filePrefix}_${new Date().toISOString().slice(0,10)}.xls`;anchor.click();URL.revokeObjectURL(url);}
function ReportKpiBars({rows}:{rows:AnyRecord[]}){const max=Math.max(100,...rows.map(row=>Number(row.total)||0));return <div className="report-kpi-bars"><div className="report-subsection-title">BIỂU ĐỒ ĐIỂM KPI 100 ĐIỂM CỦA NHÂN VIÊN</div>{rows.length?rows.map((row,index)=><div className="report-kpi-bar-row" key={row.staffId||row.name||index}><span>{row.name||'—'}</span><div><i style={{width:`${Math.max(0,Math.min(100,(Number(row.total)||0)/max*100))}%`,background:row.rankingColor||'#16a34a'}}/></div><b>{row.total||0}</b></div>):<div className="empty compact">Chưa có dữ liệu KPI để dựng biểu đồ.</div>}</div>}
function ReportIssueInlineTable({rows,onSave}:{rows:AnyRecord[];onSave:(body:AnyRecord)=>void}){return <div><p className="report-autosave-hint">Các ô đã chỉnh sửa sẽ tự động lưu khi rời khỏi ô nhập.</p><div className="table-wrap"><table className="report-inline-table report-issue-inline-table"><thead><tr><th>Mã</th><th>Ngày</th><th>Bộ phận</th><th>Nội dung</th><th>Nguyên nhân</th><th>Phương án</th><th>Phụ trách</th><th>Hạn</th><th>Trạng thái</th><th>Kiến nghị</th><th>Ghi chú</th></tr></thead><tbody>{rows.length?rows.map(row=><ReportIssueInlineRow key={row.row_no||row.id} row={row} onSave={onSave}/>):<tr><td colSpan={11} className="empty-cell">Chưa có dữ liệu.</td></tr>}</tbody></table></div></div>}
function ReportIssueInlineRow({row,onSave}:{row:AnyRecord;onSave:(body:AnyRecord)=>void}){const[state,setState]=useState({...row});const save=(field:string)=>onSave({kind:'ISSUE',row_no:row.row_no,[field]:state[field]});const input=(field:string,area=false)=><>{area?<textarea rows={2} value={text(state[field])} onChange={e=>setState(x=>({...x,[field]:e.target.value}))} onBlur={()=>save(field)}/>:<input value={text(state[field])} onChange={e=>setState(x=>({...x,[field]:e.target.value}))} onBlur={()=>save(field)}/>}</>;return <tr><td>{row.id||'—'}</td><td>{input('date')}</td><td>{input('department')}</td><td>{input('issue',true)}</td><td>{input('cause',true)}</td><td>{input('action',true)}</td><td>{input('owner')}</td><td>{input('deadline')}</td><td>{input('status')}</td><td>{input('recommendation',true)}</td><td>{input('note',true)}</td></tr>}
function CssdReportPanel({filters}:{filters:AnyRecord}){const[data,setData]=useState<AnyRecord|null>(null);const[loading,setLoading]=useState(true);useEffect(()=>{let active=true;setLoading(true);fetch(`/api/report/cssd?from=${encodeURIComponent(filters?.from||'')}&to=${encodeURIComponent(filters?.to||'')}`,{cache:'no-store'}).then(async response=>{const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Không tải được dữ liệu DỤNG CỤ');if(active)setData(result);}).catch(error=>{if(active)setData({ok:false,error:error instanceof Error?error.message:'Không tải được dữ liệu DỤNG CỤ'});}).finally(()=>{if(active)setLoading(false);});return()=>{active=false};},[filters?.from,filters?.to]);const metrics=[['Tổng lượt/bộ ghi nhận',data?.total||0],['Bộ dụng cụ khác nhau',data?.uniqueSets||0],['Ngày có hoạt động',data?.activeDays||0],['Bình quân/ngày hoạt động',data?.avgPerActiveDay||0],['Bình quân/ngày lịch',data?.avgPerCalendarDay||0],['Cao nhất/ngày',`${data?.peakCount||0}${data?.peakDay?` (${data.peakDay})`:''}`],['Định mức/ngày',data?.targetPerDay||'Chưa đặt'],['% công suất theo định mức',data?.utilizationPct==null?'Chưa đặt định mức':`${data.utilizationPct}%`]];const daily=(data?.daily||[]) as AnyRecord[];const max=Math.max(1,...daily.map(x=>Number(x.total)||0));return <section className="panel-card report-cssd-panel"><div className="toolbar-line"><div><h3>⚙ CÔNG SUẤT HOẠT ĐỘNG CSSD</h3><p className="muted">Dữ liệu lấy theo cấu hình đường link báo cáo DỤNG CỤ và kỳ đang chọn.</p></div><span className="report-source-badge">{data?.sourceSheet||'DỤNG CỤ BẬN'}</span></div>{loading?<p>Đang tải dữ liệu CSSD...</p>:!data?.configured?<div className="report-config-warning">Chưa cấu hình đường link dữ liệu DỤNG CỤ. Vào Cài đặt → Nguồn báo cáo DỤNG CỤ để nhập link Google Sheet.</div>:!data?.ok?<div className="report-config-warning danger">Không tải được dữ liệu CSSD: {data?.error}</div>:<><div className="cssd-metric-grid">{metrics.map(([label,value])=><div key={text(label)}><small>{label}</small><b>{value}</b></div>)}</div><div className="cssd-status-grid"><div><span>ĐỦ</span><b>{data.statusSummary?.DU||0}</b></div><div className="danger"><span>THIẾU</span><b>{data.statusSummary?.THIEU||0}</b></div><div className="danger"><span>HẾT HẠN</span><b>{data.statusSummary?.HET_HAN||0}</b></div><div><span>TRẠNG THÁI KHÁC</span><b>{data.statusSummary?.KHAC||0}</b></div></div><div className="cssd-daily-chart"><b>SẢN LƯỢNG XỬ LÝ DỤNG CỤ THEO NGÀY</b><div className="cssd-bars">{daily.length?daily.map((item,index)=><div className="cssd-bar-item" key={item.date||index}><strong>{item.total||0}</strong><i style={{height:`${Math.max(4,(Number(item.total)||0)/max*100)}%`}}/><span>{item.date||'—'}</span></div>):<span className="empty compact">Chưa có dữ liệu theo ngày.</span>}</div></div><div className="table-wrap"><table><thead><tr><th>Ngày</th><th>Tổng</th><th>Đủ</th><th>Thiếu</th><th>Hết hạn</th><th>Khác</th></tr></thead><tbody>{daily.length?daily.map((item,index)=><tr key={item.date||index}><td>{item.date}</td><td>{item.total||0}</td><td>{item.DU||0}</td><td>{item.THIEU||0}</td><td>{item.HET_HAN||0}</td><td>{item.KHAC||0}</td></tr>):<tr><td colSpan={6} className="empty-cell">Chưa có sản lượng trong kỳ.</td></tr>}</tbody></table></div><div className="cssd-detail-grid"><div><h4>DỤNG CỤ THIẾU</h4><DataTable rows={data.thieuList||[]} columns={['date','tenBo','nguoiGiao','nguoiNhan','ghiChu']} headers={['Ngày','Tên bộ','Người giao','Người nhận','Ghi chú']}/></div><div><h4>DỤNG CỤ HẾT HẠN</h4><DataTable rows={data.hetHanList||[]} columns={['date','tenBo','nguoiGiao','nguoiNhan','ghiChu']} headers={['Ngày','Tên bộ','Người giao','Người nhận','Ghi chú']}/></div></div></>}</section>}
function ScriptReportsView({payload,onCreate,onEdit,onRemove,onInline}:{payload:AnyRecord;onCreate:()=>void;onEdit:(row:AnyRecord)=>void;onRemove:(row:AnyRecord)=>void;onInline:(body:AnyRecord)=>void}){
 const selected=Array.isArray(payload.filters?.reportSection)?payload.filters.reportSection as string[]:text(payload.filters?.reportSection||'').split(',').filter(Boolean);
 const show=(name:string)=>!selected.length||selected.includes(name);
 const summary=payload.summary||{},hero=payload.reportHero,matrices=(payload.formMatrices||[]) as AnyRecord[];
 const[selectedMatrixCode,setSelectedMatrixCode]=useState('');useEffect(()=>{if(matrices.length&&!selectedMatrixCode)setSelectedMatrixCode(text(matrices[0].formCode));if(selectedMatrixCode&&!matrices.some(item=>sameValue(item.formCode,selectedMatrixCode)))setSelectedMatrixCode(text(matrices[0]?.formCode||''));},[matrices,selectedMatrixCode]);const visibleMatrices=selectedMatrixCode?matrices.filter(item=>sameValue(item.formCode,selectedMatrixCode)):matrices;
 const reportRows=(payload.rows||[]) as AnyRecord[];
 const heroFocus:Record<string,string[]>={
  vsmt:['Vệ sinh buồng bệnh, khu vực chung','Vệ sinh hành lang, cầu thang, thang máy','Thu gom, phân loại, vận chuyển chất thải','Kiểm tra dụng cụ và phương tiện vệ sinh','Đảm bảo môi trường xanh – sạch – đẹp'],
  cssd:['Tiếp nhận, phân loại dụng cụ','Làm sạch, khử khuẩn, tiệt khuẩn','Kiểm tra chất lượng sau tiệt khuẩn','Lưu trữ, bảo quản dụng cụ vô khuẩn','Cấp phát dụng cụ an toàn, đúng quy trình'],
  linen:['Tiếp nhận, phân loại đồ vải','Giặt, sấy, là, gấp theo quy trình','Kiểm tra chất lượng đồ vải sạch','Lưu trữ, bảo quản đồ vải','Cấp phát đồ vải đầy đủ, kịp thời'],
  monitor:['Giám sát tuân thủ quy trình KSNK','Giám sát vệ sinh tay, PPE','Giám sát môi trường, dụng cụ, đồ vải','Theo dõi và báo cáo chỉ số KSNK','Đào tạo, truyền thông và cải tiến']
 };
 const focus=heroFocus[hero?.key||'']||[];
 const issueRows=(payload.issues||[]) as AnyRecord[];
 return <div className="module-stack">
  {hero&&<div className="panel-card report-hero" style={{borderTopColor:hero.accent,borderBottomColor:hero.accent}}><div className="report-hero-main"><div className="report-hero-brand"><span className="report-hero-logo">115</span><div><b>BỆNH VIỆN NGOẠI KHOA 115 NGHỆ AN</b><small>“Tất cả vì sức khỏe của bạn”</small><strong>KHOA KSNK</strong></div></div><div className="report-hero-title">{hero.title}</div><div className="report-hero-department">{hero.department}</div><div className="report-hero-subtitle">{hero.subtitle}</div><span className="report-hero-period">▣ TỪ {formatDate(payload.filters?.from)} → {formatDate(payload.filters?.to)}</span><em>{hero.slogan}</em></div><div className="report-focus-card"><div className="report-focus-icon">{hero.icon||'✦'}</div><h4>NỘI DUNG TRỌNG TÂM</h4>{focus.map((item,index)=><div className="report-focus-item" key={item}><span>{index+1}</span><b>{item}</b></div>)}<div className="report-focus-slogan">{hero.slogan}</div></div><div className="report-hero-footer">Làm đúng, ngay cả khi không ai nhìn thấy</div></div>}
  {hero?.key==='cssd'&&<CssdReportPanel filters={payload.filters||{}}/>}<div className="summary-cards"><div><b>{summary.taskTotal||0}</b><span>Giao việc</span></div><div><b>{summary.taskDone||0}</b><span>CV hoàn thành</span></div><div><b>{summary.overdue||0}</b><span>CV quá hạn</span></div><div><b>{summary.weeklyTotal||0}/{summary.monthlyTotal||0}</b><span>Kế hoạch tuần/tháng</span></div><div><b>{summary.checklistForms||0}</b><span>Phiếu bảng kiểm</span></div><div><b>{summary.violationCount||0}</b><span>Vi phạm</span></div><div><b>{summary.issueCount||0}</b><span>Tồn tại</span></div></div>
  <div style={{display:show('weekly')?undefined:'none'}} className="panel-card"><h3>1. KẾ HOẠCH TUẦN CỦA BỘ PHẬN</h3><ReportInlineTable rows={payload.weekly||[]} kind="PLAN" onSave={onInline}/></div>
  <div style={{display:show('monthly')?undefined:'none'}} className="panel-card"><h3>2. KẾ HOẠCH THÁNG CỦA BỘ PHẬN</h3><ReportInlineTable rows={payload.monthly||[]} kind="PLAN" onSave={onInline}/></div>
  <div style={{display:show('tasks')?undefined:'none'}} className="panel-card"><h3>3. CÔNG VIỆC TRỌNG ĐIỂM &amp; ĐỘT XUẤT</h3><ReportInlineTable rows={payload.tasks||[]} kind="TASK" onSave={onInline}/></div>
  <div style={{display:show('overview')?undefined:'none'}} className="panel-card"><h3>4. CHỈ SỐ TỔNG QUAN</h3><DataTable rows={reportRows} columns={['department','taskCount','completedTasks','overdueTasks','violationCount','violationPoints','checklistCount','checklistApplied','checklistPass','checklistFails','checklistNa','checklistRate','planCount','openPlans','issueCount']} headers={['Bộ phận','Tổng CV','Hoàn thành','Quá hạn','Vi phạm','Điểm trừ','Phiếu kiểm','Áp dụng','Đạt','Không đạt','K.A.D','Tỷ lệ %','Kế hoạch','Chưa xong','Tồn tại']}/></div>
  <div style={{display:show('checklists')?undefined:'none'}} className="panel-card"><h3>5. PHÂN TÍCH BẢNG KIỂM</h3><DataTable rows={payload.checks||[]} columns={['date','formCode','formName','person','department','applied','pass','fail','na','rate','percentRank','percentKpi','note']} headers={['Ngày','Mã phiếu','Tên phiếu','Nhân viên','Bộ phận','Áp dụng','Đạt','Không đạt','K.A.D','Tỷ lệ %','Xếp loại','KPI phiếu','Ghi chú']}/><p className="report-conclusion">Tỷ lệ đạt bình quân: {summary.checklistAvgRate||0}% · Không đạt: {summary.checklistFails||0} · Không áp dụng: {summary.checklistNa||0}</p></div>
  <div style={{display:show('routine')?undefined:'none'}} className="panel-card"><h3>⚠ 6. THỐNG KÊ &amp; PHÂN TÍCH LỖI THƯỜNG QUY</h3><ReportErrorStatsTable rows={payload.errorStats||[]}/><div className="report-analysis-box"><b>Kết luận &amp; phân tích:</b>{(payload.routineAnalysis||[]).map((item:string,index:number)=><p key={index}>{item}</p>)}</div><ReportOpinionEditor opinions={payload.opinions||[]} filters={payload.filters||{}} formCode="__ROUTINE__" formName="LỖI THƯỜNG QUY" onSave={onInline}/></div>
  <div style={{display:show('sudden')?undefined:'none'}} className="panel-card"><h3>🚨 7. THỐNG KÊ LỖI ĐỘT XUẤT / VI PHẠM</h3><div className="report-analysis-box"><b>Kết luận &amp; phân tích:</b>{(payload.suddenAnalysis||[]).map((item:string,index:number)=><p key={index}>{item}</p>)}</div><ReportErrorStatsTable rows={payload.suddenErrorStats||[]}/><DataTable rows={payload.violations||[]} columns={['date','person','department','errorName','level','points','recorder','status','note','imageName','documentName']} headers={['Ngày','Nhân viên','Bộ phận','Tên lỗi','Mức độ','Điểm trừ','Người ghi nhận','Trạng thái','Ghi chú','Ảnh','Tài liệu']}/><ReportOpinionEditor opinions={payload.opinions||[]} filters={payload.filters||{}} formCode="__SUDDEN__" formName="LỖI ĐỘT XUẤT / VI PHẠM" onSave={onInline}/></div>
  <div style={{display:show('matrix')?undefined:'none'}} className="panel-card"><div className="toolbar-line"><div><h3>👥 8. MA TRẬN THEO TỪNG PHIẾU GIÁM SÁT</h3><p className="muted">Chọn đúng phiếu cần xem; mặc định mở phiếu đầu tiên trong kỳ.</p></div><select className="report-matrix-picker" value={selectedMatrixCode} onChange={e=>setSelectedMatrixCode(e.target.value)}><option value="">Tất cả phiếu</option>{matrices.map((matrix,index)=><option key={matrix.formCode||index} value={matrix.formCode||''}>{matrix.formCode||'—'} - {matrix.formName||'Chưa có tên'}</option>)}</select></div>{visibleMatrices.length?visibleMatrices.map((matrix:AnyRecord,index:number)=><div className="report-matrix-card" key={matrix.formCode||index}><div className="report-matrix-head">8.{index+1} — {matrix.formCode||''} — {matrix.formName||''}</div><div className="report-matrix-body"><ReportMatrixMetrics matrix={matrix}/><ReportMatrixTable matrix={matrix}/><ReportMatrixStaffSummary rows={matrix.summary||[]}/><div className="report-form-error-block"><h5>7. CHI TIẾT LỖI &amp; HÌNH ẢNH GHI NHẬN{matrix.formCode&&<> — {matrix.formCode}</>}</h5><ReportErrorDetailTable rows={matrix.errorDetails||[]}/></div><div className="report-analysis-box"><b>Kết luận &amp; phân tích:</b><p>{matrix.conclusion||'Không có kết luận.'}</p></div><ReportOpinionEditor opinions={payload.opinions||[]} filters={payload.filters||{}} formCode={matrix.formCode||''} formName={matrix.formName||''} onSave={onInline}/></div></div>):<div className="empty compact">Chưa có dữ liệu ma trận bảng kiểm.</div>}</div>
  <div style={{display:show('kpi')?undefined:'none'}} className="panel-card"><div className="toolbar-line"><div><h3>📊 9. KPI 100 ĐIỂM — ĐÚNG LOGIC MENU KPI</h3><p className="muted">Công thức: 100 + điểm giao việc + điểm bảng kiểm − điểm vi phạm.</p></div><button type="button" className="add-btn" onClick={()=>exportKpiExcel((payload.kpiReport?.rows||[]) as AnyRecord[],payload.kpiReport?.summary||{})}>⇩ XUẤT EXCEL</button></div><div className="report-kpi-summary"><div><small>Tổng điểm gốc</small><b>{(payload.kpiReport?.rows||[]).reduce((sum:number,row:AnyRecord)=>sum+Number(row.base||0),0)}</b></div><div><small>Điểm giao việc</small><b>{(payload.kpiReport?.rows||[]).reduce((sum:number,row:AnyRecord)=>sum+Number(row.taskScore||0),0)}</b></div><div><small>Điểm bảng kiểm</small><b>{(payload.kpiReport?.rows||[]).reduce((sum:number,row:AnyRecord)=>sum+Number(row.checklistScore||0),0)}</b></div><div><small>Điểm vi phạm</small><b>{(payload.kpiReport?.rows||[]).reduce((sum:number,row:AnyRecord)=>sum+Number(row.violationScore||0),0)}</b></div><div><small>KPI bình quân</small><b>{payload.kpiReport?.summary?.averageScore||0}</b></div></div><DataTable rows={payload.matrixRows||[]} columns={['staffId','name','department','formCodes','forms','evaluated','pass','fail','errorRate']} headers={['Mã NV','Họ tên','Bộ phận','Phiếu','Số phiếu','Đánh giá','Đạt','Không đạt','Tỷ lệ lỗi %']}/><DataTable rows={payload.kpiReport?.rows||[]} columns={['staffId','name','department','position','base','taskScore','checklistScore','violationScore','total','ranking','taskCount','checkCount','violationCount','details']} headers={['Mã NV','Họ tên','Bộ phận','Chức vụ','Gốc','Giao việc','Bảng kiểm','Vi phạm','Tổng KPI','Xếp loại','CV','BK','VP','Chi tiết']}/><ReportKpiBars rows={payload.kpiReport?.rows||[]}/><div className="report-analysis-box"><b>Kết luận &amp; phân tích:</b><p>{payload.kpiReport?.conclusion||'Chưa đủ dữ liệu KPI.'}</p></div><ReportOpinionEditor opinions={payload.opinions||[]} filters={payload.filters||{}} formCode="__TONG_THE__" formName="KẾT LUẬN TỔNG THỂ KPI" onSave={onInline}/></div>
  <div style={{display:show('incidents')?undefined:'none'}} className="panel-card"><h3>📕 10. NHẬT KÝ SỰ CỐ</h3><ReportIssueInlineTable rows={payload.incidentIssues||[]} onSave={onInline}/></div>
  <div style={{display:show('issues')?undefined:'none'}} className="panel-card"><h3>📌 11. TỒN TẠI KHÁC &amp; KIẾN NGHỊ</h3><ReportIssueInlineTable rows={payload.otherIssues||issueRows} onSave={onInline}/><p>{payload.special?.conclusion||''}</p></div>
  <div style={{display:show('next-week')?undefined:'none'}} className="panel-card"><h3>📅 12. DANH SÁCH KẾ HOẠCH TUẦN SAU</h3><ReportNextWeekTable rows={payload.nextWeekPlan||[]} onSave={onInline}/></div>
 </div>;
}

function TaskApprovalQueue({items,onEdit,onFilterApproval,managerFilter}:{items:AnyRecord[];onEdit:(row:AnyRecord)=>void;onFilterApproval:()=>void;managerFilter?:string}){const managerSelected=Boolean(text(managerFilter));const visibleItems=managerSelected?items:[];const waitingCount=visibleItems.filter(x=>isWaitingManager(x.approvalStatus)).length;return <div className="panel-card approval-queue"><div className="toolbar-line"><div><h3>📌 DANH MỤC XIN PHÊ DUYỆT CỦA QUẢN LÝ</h3><p className="muted">Chọn tên quản lý ở bộ lọc “Quản lý phê duyệt” phía trên. Chỉ các công việc giao cho người đó mới được hiển thị.</p></div><button type="button" className="approval-queue-count approval-queue-filter" onClick={onFilterApproval} disabled={!managerSelected}>{managerSelected?`CHỜ PHÊ DUYỆT: ${waitingCount}`:'CHỌN QUẢN LÝ ĐỂ XEM'}</button></div>{!managerSelected?<div className="approval-queue-gate"><b>Chưa hiển thị danh mục phê duyệt</b><span>Gõ tên → lọc → chọn người có Chức vụ quản lý để tải đúng các nội dung giao việc cần người đó xem xét.</span></div>:visibleItems.length?<div className="approval-queue-list">{visibleItems.slice(0,12).map(row=>{const waitingManager=isWaitingManager(row.approvalStatus);const action=waitingManager?'review':'feedback';return <button type="button" key={row.row_no||row.id} className="approval-queue-item" onClick={()=>onEdit({...row,__module:'taskApproval',approvalAction:action})}><span><b>{row.title||'Công việc chưa có tiêu đề'}</b><small>{[row.assignee,row.managerName,row.department].filter(Boolean).join(' · ')}</small><em>{waitingManager?'Việc cần làm: mở Chi tiết giao việc, xem minh chứng, chọn Đánh giá quản lý hiện tại rồi Phê duyệt hoặc Yêu cầu bổ sung.':'Việc cần làm: đọc ý kiến quản lý, bổ sung nội dung/tài liệu và gửi phản hồi.'}</em><ApprovalSteps status={row.approvalStatus} action={action} compact/><em>{row.approvalRequest||row.approvalResponse||'Mở chi tiết giao việc để xem nội dung'}</em></span><Badge value={waitingManager?'CHỜ PHÊ DUYỆT':`CHỜ ${row.assignee||'NHÂN VIÊN'} PHẢN HỒI`}/></button>})}</div>:<div className="empty compact">Người quản lý này chưa có nội dung xin phê duyệt hoặc phản hồi đang chờ.</div>}</div>}
function TaskSummaryCards({summary}:{summary:AnyRecord}){const scope=summary.scopeName||'TỔNG THỂ';return <section className="panel-card task-summary-panel"><div className="task-summary-heading"><div><h3>📊 TỔNG HỢP CÔNG VIỆC</h3><p>Phạm vi hiện tại: <b>{scope}</b>. Các số liệu thay đổi theo bộ phận, tên người thực hiện, thời gian và bộ lọc đang chọn.</p></div><span className="task-summary-scope">{scope==='TỔNG THỂ'?'TOÀN BỘ':'THEO CÁ NHÂN'}</span></div><div className="summary-cards task-summary-cards"><div className="task-summary-total"><b>{summary.total||0}</b><span>Tổng công việc</span></div><div className="task-summary-start"><b>{summary.notStarted||0}</b><span>Chưa bắt đầu</span></div><div className="task-summary-progress"><b>{summary.inProgress||0}</b><span>Đang làm</span></div><div className="task-summary-done"><b>{summary.completed||0}</b><span>Đã hoàn thành</span></div><div className="task-summary-overdue"><b>{summary.overdue||0}</b><span>Quá hạn</span></div><div className="task-summary-approval"><b>{summary.pendingApproval||0}</b><span>Chờ phê duyệt / phản hồi</span></div></div></section>}
function WorkloadPanel({rows}:{rows:AnyRecord[]}){return <div className="panel-card workload-panel"><div className="toolbar-line"><h3>👥 SỐ LƯỢNG CÔNG VIỆC THEO NHÂN VIÊN</h3><small className="muted">Không tính KPI</small></div><DataTable rows={rows} columns={['name','activeCount','completed','overdue','waitingManager','waitingEmployee','totalTasks']} headers={['Nhân viên','Đang làm','Đã hoàn thành','Quá hạn','Chờ quản lý','Chờ phản hồi','Tổng công việc']}/></div>}
function AlertTable({rows,onOpenAlert,onFilterManager}:{rows:AnyRecord[];onOpenAlert:(alert:AnyRecord)=>void;onFilterManager:(managerName:string)=>void}){const safeRows=recordArray(rows).filter(x=>!isViolationAlert(x));return <div className="table-wrap alert-table-wrap"><table><thead><tr><th>Mức cảnh báo</th><th>Nguồn</th><th>Ngày</th><th>Nội dung / Hướng dẫn</th><th>Nhân viên</th><th>Quản lý</th><th>Trạng thái</th><th>Phản hồi</th><th></th></tr></thead><tbody>{safeRows.length?safeRows.map((row,index)=><tr key={row.row_no||row.id||index}><td><Badge value={row.level}/></td><td>{row.kind||'—'}</td><td>{formatDate(row.date)}</td><td title={row.title}><b>{row.title||'—'}</b>{row.instruction&&<small className="alert-sub">Việc cần làm: {row.instruction}</small>}{row.approvalRequest&&<small className="alert-sub">Xin phê duyệt: {row.approvalRequest}</small>}{row.approvalResponse&&<small className="alert-sub">Ý kiến quản lý: {row.approvalResponse}</small>}{row.managerOpinion&&<small className="alert-sub">Ý kiến quản lý mới: {row.managerOpinion}</small>}{approvalActionForAlert(row)&&<ApprovalSteps status={row.approvalStatus} action={approvalActionForAlert(row)} compact/>}</td><td>{row.person||'—'}</td><td>{row.managerName?<button type="button" className="alert-manager-link" onClick={()=>onFilterManager(row.managerName)}>{row.managerName}</button>:'—'}</td><td><Badge value={approvalLabel(row.approvalStatus||row.contractAlert||row.status||row.level)}/></td><td>{row.employeeFeedback||'Chưa có phản hồi'}</td><td className="alert-actions"><button type="button" className="edit-btn" onClick={()=>onOpenAlert(row)}>MỞ &amp; XỬ LÝ</button></td></tr>):<tr><td colSpan={9} className="empty-cell">Không có cảnh báo phù hợp.</td></tr>}</tbody></table></div>}

function leaveNumber(value:any){const number=Number(value||0);return Number.isInteger(number)?String(number):number.toFixed(1);}
function LeavePlanningPanel({rows,summary,meta}:{rows:AnyRecord[];summary:AnyRecord;meta:AnyRecord}){
 return <div className="panel-card leave-planning-panel"><div className="toolbar-line leave-planning-heading"><div><h3>PHÂN BỔ NGHỈ PHÉP THEO BỘ PHẬN</h3><p className="muted">Kỳ theo dõi {meta.currentMonthLabel||'hiện tại'} · còn {meta.monthsRemaining||0} tháng (tính cả tháng hiện tại). Mốc tham chiếu: tối đa 1 ngày/người/tháng để nhận diện bộ phận cần ưu tiên bố trí.</p></div><span className="leave-plan-period">Năm {meta.year||new Date().getFullYear()}</span></div><div className="summary-cards leave-planning-summary"><div><b>{summary.activeEmployees||0}</b><span>Nhân sự đang làm</span></div><div><b>{summary.employeesWithLeaveRemaining||0}</b><span>Nhân sự còn phép</span></div><div><b>{leaveNumber(summary.remaining)}</b><span>Tổng ngày còn lại</span></div><div><b>{leaveNumber(summary.averageDaysPerMonth)}</b><span>Ngày cần bố trí/tháng</span></div><div><b>{summary.departmentsNeedingPlan||0}</b><span>Bộ phận còn phép</span></div><div><b>{summary.highPriorityDepartments||0}</b><span>Bộ phận ưu tiên cao</span></div></div><div className="table-wrap leave-planning-table"><table><thead><tr><th>Bộ phận</th><th>Nhân sự đang làm</th><th>Còn phép</th><th>Ngày phép còn lại</th><th>Tối thiểu nghỉ/tháng</th><th>Bình quân ngày/tháng</th><th>Áp lực tham chiếu</th><th>Cảnh báo / đề xuất</th></tr></thead><tbody>{rows.length?rows.map((row,index)=><tr key={row.department||index} className={row.warningLevel==='CAO'?'leave-plan-high':row.warningLevel==='CẦN LẬP KẾ HOẠCH'?'leave-plan-warn':''}><td><b>{row.department||'Chưa xác định'}</b><details className="leave-staff-details"><summary>Xem nhân sự</summary><div>{(row.staff||[]).length?(row.staff||[]).map((person:AnyRecord,personIndex:number)=><span key={person.id||person.name||personIndex}>{person.name} · {leaveNumber(person.leaveRemaining)} ngày</span>):<small>Không có nhân sự đang làm</small>}</div></details></td><td>{row.activeEmployees||0}</td><td>{row.employeesWithLeaveRemaining||0} người</td><td className="leave-number">{leaveNumber(row.remainingDays)} ngày</td><td>{row.minimumEmployeesPerMonth||0} người</td><td className="leave-number">{leaveNumber(row.averageDaysPerMonth)} ngày</td><td><span className={`leave-plan-badge ${row.warningLevel==='CAO'?'high':row.warningLevel==='CẦN LẬP KẾ HOẠCH'?'warn':'ok'}`}>{row.warningLevel}</span><small className="leave-plan-ratio">{leaveNumber((row.pressureRatio||0)*100)}% công suất tham chiếu</small></td><td><b>{row.warningMessage}</b></td></tr>):<tr><td colSpan={8} className="empty-cell">Chưa có dữ liệu phân bổ nghỉ phép.</td></tr>}</tbody></table></div></div>;
}
function StaffDirectoryTable({rows,onEdit,onRemove}:{rows:AnyRecord[];onEdit:(row:AnyRecord)=>void;onRemove:(row:AnyRecord)=>void}){return <div className="table-wrap staff-directory-table"><table><thead><tr><th>Mã NV</th><th>Họ và tên</th><th>Bộ phận</th><th>Chức vụ</th><th>Số điện thoại</th><th>Ngày ký HĐ</th><th>Ngày hết hạn HĐ</th><th>Cảnh báo HĐ</th><th>Phép năm</th><th>Đã nghỉ</th><th>Còn lại</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>{rows.length?rows.map((row,index)=><tr key={row.row_no||row.id||index}><td>{row.id||'—'}</td><td>{row.name||'—'}</td><td>{row.department||'—'}</td><td><b>{row.position||'—'}</b></td><td>{row.phone||'—'}</td><td>{formatDate(row.contractStartDate)}</td><td>{formatDate(row.contractEndDate)}</td><td><Badge value={row.contractAlert}/></td><td className="leave-number">{row.annualLeaveEntitlement||0} ngày</td><td className="leave-number">{row.leaveTaken||0} ngày</td><td className={Number(row.leaveRemaining||0)<=0?'leave-number text-danger':'leave-number text-ok'}>{row.leaveRemaining||0} ngày</td><td>{row.status||'—'}</td><td className="actions-cell"><button className="edit-btn" onClick={()=>onEdit(row)}>SỬA</button><button className="leave-btn" onClick={()=>onEdit({...row,__leaveEntry:true})}>+ NGHỈ PHÉP</button><button className="danger" onClick={()=>onRemove(row)}>XÓA</button></td></tr>):<tr><td colSpan={13} className="empty-cell">Chưa có dữ liệu nhân sự.</td></tr>}</tbody></table></div>}

function kpiRankTextColor(color:any){const value=text(color).toLowerCase();return ['#f59e0b','#fbbf24','#facc15','#eab308'].includes(value)?'#172033':'#fff';}
function kpiScoreClass(value:any){const number=Number(value)||0;return number>0?'kpi-score-positive':number<0?'kpi-score-negative':'kpi-score-zero';}
function kpiScoreText(value:any,showPlus=false){const number=Number(value)||0;return showPlus&&number>0?`+${number}`:String(number);}
function KpiConversionTable({rules,onEdit}:{rules:AnyRecord[];onEdit?:(row:AnyRecord)=>void}){return <div className="table-wrap kpi-conversion-table"><table><thead><tr><th>STT</th><th>XẾP LOẠI</th><th>TỪ ĐIỂM</th><th>ĐẾN ĐIỂM</th><th>MÀU</th></tr></thead><tbody>{rules.length?rules.map((rule,index)=><tr key={rule.row_no||rule.ranking||index}><td>{rule.order||index+1}</td><td><b>{rule.ranking||'—'}</b></td><td>{rule.min}</td><td>{rule.max}</td><td><span className="kpi-color-chip" style={{backgroundColor:rule.color||'#6C757D',color:kpiRankTextColor(rule.color)}}>{rule.color||'—'}</span></td></tr>):<tr><td colSpan={5} className="empty-cell">Chưa có cấu hình quy đổi KPI.</td></tr>}</tbody></table></div>}

function KpiRuleEditor({rules,onSaved}:{rules:AnyRecord[];onSaved:()=>void}){
 const [items,setItems]=useState<AnyRecord[]>(()=>rules.map((rule,index)=>({...rule,order:rule.order||index+1,color:rule.color||'#6C757D',status:rule.status||'Hoạt động'})));
 const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');
 useEffect(()=>{setItems(rules.map((rule,index)=>({...rule,order:rule.order||index+1,color:rule.color||'#6C757D',status:rule.status||'Hoạt động'})));},[rules]);
 const update=(index:number,key:string,value:any)=>setItems(current=>current.map((item,position)=>position===index?{...item,[key]:value}:item));
 const add=()=>setItems(current=>[...current,{order:current.length+1,ranking:'',min:0,max:0,color:'#6C757D',status:'Hoạt động'}]);
 const remove=(index:number)=>setItems(current=>current.filter((_,position)=>position!==index).map((item,position)=>({...item,order:position+1})));
 async function save(){
  setMessage('');setError('');const sorted:AnyRecord[]=items.map(item=>({...item,min:Number(item.min),max:Number(item.max)})).sort((a,b)=>a.min-b.min);
  if(!items.length){setError('Phải có ít nhất một mức xếp loại KPI.');return;}
  if(items.some(item=>!text(item.ranking)||!Number.isFinite(Number(item.min))||!Number.isFinite(Number(item.max))||Number(item.max)<Number(item.min))){setError('Mỗi mức phải có tên và khoảng điểm hợp lệ.');return;}
  for(let index=1;index<sorted.length;index++){if(Number(sorted[index].min)<=Number(sorted[index-1].max)){setError(`Khoảng điểm KPI bị chồng lấn giữa “${sorted[index-1].ranking}” và “${sorted[index].ranking}”.`);return;}}
  setBusy(true);try{const response=await fetch('/api/modules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:'rule',op:'save_rules',rows:items.map((item,index)=>({...item,order:index+1}))})});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Không lưu được quy đổi KPI.');setMessage('Đã lưu cấu hình quy đổi điểm và tự cập nhật bảng KPI.');onSaved();}catch(reason){setError(reason instanceof Error?reason.message:'Không lưu được quy đổi KPI.');}finally{setBusy(false);}
 }
 return <div className="kpi-rule-editor"><div className="kpi-rule-editor-note">Các khoảng điểm không được chồng lấn. Ví dụ: TỐT 95–109.99 thì KHÁ phải kết thúc tối đa 94.99.</div>{error&&<div className="validation-alert" role="alert">⚠ {error}</div>}{message&&<div className="success-box" role="status">✓ {message}</div>}<div className="table-wrap kpi-rule-editor-table"><table><thead><tr><th>STT</th><th>XẾP LOẠI</th><th>TỪ ĐIỂM</th><th>ĐẾN ĐIỂM</th><th>MÀU</th><th>XÓA</th></tr></thead><tbody>{items.length?items.map((item,index)=><tr key={item.row_no||`new-${index}`}><td>{index+1}</td><td><input value={text(item.ranking)} onChange={e=>update(index,'ranking',e.target.value)} placeholder="XUẤT SẮC"/></td><td><input type="number" step="0.01" value={text(item.min)} onChange={e=>update(index,'min',e.target.value)}/></td><td><input type="number" step="0.01" value={text(item.max)} onChange={e=>update(index,'max',e.target.value)}/></td><td><label className="kpi-color-input"><input type="color" value={/^#[0-9a-f]{6}$/i.test(text(item.color))?item.color:'#6C757D'} onChange={e=>update(index,'color',e.target.value)}/><code>{item.color||'#6C757D'}</code></label></td><td><button type="button" className="danger" onClick={()=>remove(index)} disabled={busy}>🗑</button></td></tr>):<tr><td colSpan={6} className="empty-cell">Chưa có mức xếp loại.</td></tr>}</tbody></table></div><div className="kpi-rule-editor-actions"><button type="button" className="edit-btn" onClick={add} disabled={busy}>＋ THÊM MỨC</button><button type="button" className="add-btn" onClick={save} disabled={busy}>{busy&&<span className="save-spinner" aria-hidden="true"/>}{busy?'ĐANG LƯU…':'▣ LƯU QUY ĐỔI'}</button></div></div>;
}

function storedKpiRows(rows:AnyRecord[],rules:AnyRecord[]){return rows.map(row=>{const rank=row.rank||row.ranking||'';const details=Array.isArray(row.details)?row.details:(text(row.detail)?text(row.detail).split(' | ').filter(Boolean):[]);const rule=rules.find(item=>sameValue(item.ranking,rank));return {...row,name:row.person||row.name,ranking:rank,rankingColor:row.rankingColor||rule?.color||'#6C757D',base:row.base??100,details};});}
function storedKpiSummary(rows:AnyRecord[]){const total=rows.reduce((sum,row)=>sum+Number(row.total||0),0);return {averageScore:rows.length?Math.round(total/rows.length*10)/10:0,totalScore:total};}
function KpiHistoryPanel({stored,rules,onReload}:{stored:AnyRecord[];rules:AnyRecord[];onReload:()=>void}){
 const groups=useMemo(()=>{const map=new Map<string,AnyRecord>();stored.forEach((row,index)=>{const savedAt=text(row.savedAt||row.date);const key=text(row.snapshotId)||[row.fromDate,row.toDate,row.department,savedAt.slice(0,19)||`legacy-${index}`].join('|');const current=map.get(key)||{key,snapshotId:row.snapshotId||'',fromDate:row.fromDate,toDate:row.toDate,department:row.department,savedAt:row.savedAt||row.date,rows:[]};current.rows.push(row);map.set(key,current);});return [...map.values()].sort((a,b)=>String(b.savedAt||'').localeCompare(String(a.savedAt||'')));},[stored]);
 const [selectedKey,setSelectedKey]=useState('');const [busyKey,setBusyKey]=useState('');const selected=groups.find(group=>group.key===selectedKey)||null;
 async function remove(group:AnyRecord){if(!window.confirm(`Xóa lịch sử KPI kỳ ${formatDate(group.fromDate)} → ${formatDate(group.toDate)}${group.department?` · ${group.department}`:''}?`))return;setBusyKey(group.key);try{const response=await fetch('/api/modules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:'kpi',op:'delete_report',entries:group.rows.map((row:AnyRecord)=>({sheet:row.sheet,row_no:row.row_no}))})});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Không xóa được lịch sử KPI.');if(selectedKey===group.key)setSelectedKey('');onReload();}catch(reason){window.alert(reason instanceof Error?reason.message:'Không xóa được lịch sử KPI.');}finally{setBusyKey('');}}
 const detailRows=selected?storedKpiRows(selected.rows,rules):[];const detailSummary=storedKpiSummary(detailRows);
 return <div className="panel-card kpi-history-panel"><div className="toolbar-line"><div><h3>🗂 LỊCH SỬ LƯU KPI</h3><p className="muted">Mỗi lần bấm “LƯU BẢNG KPI” tạo một kỳ riêng. Chọn kỳ để xem đúng chi tiết đã lưu.</p></div><b>{groups.length} kỳ</b></div><div className="table-wrap kpi-history-table"><table><thead><tr><th>KỲ LƯU</th><th>TỪ NGÀY</th><th>ĐẾN NGÀY</th><th>BỘ PHẬN</th><th>SỐ NHÂN SỰ</th><th>ĐIỂM BÌNH QUÂN</th><th>THAO TÁC</th></tr></thead><tbody>{groups.length?groups.map(group=><tr key={group.key} className={selectedKey===group.key?'selected-history-row':''}><td>{group.savedAt?formatDate(group.savedAt):'—'}</td><td>{formatDate(group.fromDate)}</td><td>{formatDate(group.toDate)}</td><td>{group.department||'Tất cả bộ phận'}</td><td>{group.rows.length}</td><td>{storedKpiSummary(group.rows).averageScore.toFixed(1)}</td><td className="actions-cell"><button type="button" className="edit-btn" onClick={()=>setSelectedKey(group.key)}>{selectedKey===group.key?'ĐANG XEM':'XEM CHI TIẾT'}</button><button type="button" className="add-btn" onClick={()=>exportKpiExcel(storedKpiRows(group.rows,rules),storedKpiSummary(group.rows),`KPI_LUU_${formatDate(group.fromDate)}`)}>⇩ XUẤT EXCEL</button><button type="button" className="danger" onClick={()=>void remove(group)} disabled={busyKey===group.key}>{busyKey===group.key?'ĐANG XÓA…':'XÓA'}</button></td></tr>):<tr><td colSpan={7} className="empty-cell">Chưa có lịch sử KPI được lưu.</td></tr>}</tbody></table></div>{selected&&<div className="kpi-history-detail"><div className="toolbar-line"><div><h4>CHI TIẾT KỲ KPI ĐÃ LƯU</h4><p className="muted">{formatDate(selected.fromDate)} → {formatDate(selected.toDate)} · {selected.department||'Tất cả bộ phận'} · Lưu lúc {formatDate(selected.savedAt)}</p></div><div className="card-actions"><button type="button" className="add-btn" onClick={()=>exportKpiExcel(detailRows,detailSummary,`KPI_LUU_${formatDate(selected.fromDate)}`)}>⇩ XUẤT EXCEL</button><button type="button" className="filter-reset" onClick={()=>setSelectedKey('')}>ĐÓNG CHI TIẾT</button></div></div><KpiScoreTable rows={detailRows}/></div>}</div>;
}

function KpiDashboardV2({payload,filters,onCreate,onCreateFeedback,onInline,onReload}:{payload:AnyRecord;filters:AnyRecord;onCreate:()=>void;onCreateFeedback:()=>void;onInline:(body:AnyRecord)=>void;onReload:()=>void}){
 const rows=recordArray(payload.rows);const summary=payload.summary||{};const rules=((payload.conversionRules||payload.rules||[]) as AnyRecord[]).slice().sort((a,b)=>Number(a.order||0)-Number(b.order||0));const rankCounts=summary.rankCounts||{};const[showRules,setShowRules]=useState(false);const summaryCards=[['Số nhân viên',summary.staffCount??rows.length,'kpi-card-dark'],['KPI bình quân',summary.averageScore??0,'kpi-card-blue'],['Tổng điểm giao việc',summary.totalTaskScore??0,'kpi-card-teal'],['Tổng điểm bảng kiểm',summary.totalChecklistScore??0,'kpi-card-indigo'],['Tổng điểm vi phạm',summary.totalViolationScore??0,'kpi-card-red']];
 const lowest=rows.slice().sort((a,b)=>Number(a.total||0)-Number(b.total||0))[0];
 return <div className="module-stack kpi-dashboard"><div className="kpi-formula-bar"><b>CÔNG THỨC KPI CHÍNH THỨC:</b> 100 + điểm giao việc + điểm bảng kiểm + điểm vi phạm <small>(điểm vi phạm được lưu dưới dạng số âm)</small></div><div className="kpi-summary-grid">{summaryCards.map(([label,value,kind])=><div key={String(label)} className={String(kind)}><small>{label}</small><b>{typeof value==='number'?Number(value).toFixed(label==='KPI bình quân'?1:0):value}</b></div>)}</div><div className="kpi-ranking-grid">{rules.map((rule,index)=><div key={rule.ranking||index} style={{backgroundColor:rule.color||'#6C757D',color:kpiRankTextColor(rule.color)}}><b>{rule.ranking||'—'}</b><strong>{rankCounts[rule.ranking]||0}</strong></div>)}</div><div className="panel-card kpi-toolbar"><div><b>{rows.length} nhân sự KPI</b><p className="muted">Đang tính theo khoảng thời gian, bộ phận và nhân viên đã chọn.</p></div><div className="card-actions"><button type="button" className="add-btn" onClick={()=>exportKpiExcel(rows,summary)}>⇩ XUẤT EXCEL</button><button type="button" className="add-btn" onClick={onCreate}>LƯU BẢNG KPI</button><button type="button" className="edit-btn" onClick={onCreateFeedback}>+ GÓP Ý KPI</button><button type="button" className="edit-btn" onClick={()=>setShowRules(value=>!value)}>⚙ {showRules?'ĐÓNG QUY ĐỔI':'QUY ĐỔI XẾP LOẠI'}</button></div></div><KpiScoreTable rows={rows}/><ReportKpiBars rows={rows}/><div className="kpi-total-strip"><div><b>{summary.totalScore??0}</b><span>Tổng điểm KPI toàn bộ</span></div><div><b>{summary.totalTaskScore??0}</b><span>Tổng điểm giao việc</span></div><div><b>{summary.totalChecklistScore??0}</b><span>Tổng điểm bảng kiểm</span></div><div><b>{summary.totalViolationScore??0}</b><span>Tổng điểm vi phạm</span></div><div><b>{summary.averageScore??0}</b><span>Điểm KPI bình quân</span></div></div><div className="panel-card kpi-conclusion"><h3>📌 KẾT LUẬN KPI</h3><ul><li>{payload.conclusion||'Chưa đủ dữ liệu KPI.'}</li><li>Có {rankCounts['XUẤT SẮC']||0} nhân viên xếp loại XUẤT SẮC, {rankCounts['TỐT']||0} nhân viên xếp loại TỐT.</li><li>Điểm thấp nhất: {lowest?`${lowest.name} — ${Number(lowest.total||0).toFixed(1)} điểm.`:'Chưa có dữ liệu.'}</li></ul></div><ReportOpinionEditor opinions={(payload.opinions||[]) as AnyRecord[]} filters={filters} formCode="__KPI_MODULE__" formName="KẾT LUẬN / GÓP Ý CỦA QUẢN LÝ" onSave={onInline}/>{showRules&&<div className="panel-card kpi-rule-config-panel"><div className="toolbar-line"><div><h3>⚙ CẤU HÌNH QUY ĐỔI ĐIỂM → XẾP LOẠI</h3><p className="muted">Chỉnh sửa trực tiếp tên mức, khoảng điểm và màu; bấm lưu để áp dụng cho KPI và Báo cáo.</p></div><KpiConversionTable rules={rules}/></div><KpiRuleEditor rules={rules} onSaved={onReload}/></div>}<KpiHistoryPanel stored={(payload.stored||[]) as AnyRecord[]} rules={rules} onReload={onReload}/><div className="panel-card"><h3>GÓP Ý KPI ĐÃ LƯU</h3><DataTable rows={(payload.feedback||[]).map((x:AnyRecord)=>x.data?{...x.data,row_no:x.row_no}:x)} columns={['Mã ý kiến','Từ ngày','Đến ngày','Bộ phận','Nhân viên','Nội dung góp ý','Người nhập']} headers={['Mã','Từ','Đến','Bộ phận','Nhân viên','Nội dung','Người nhập']}/></div></div>;
}
function KpiScoreTable({rows}:{rows:AnyRecord[]}){return <div className="table-wrap kpi-score-table"><table><thead><tr><th>NHÂN VIÊN</th><th>BỘ PHẬN</th><th>ĐIỂM GỐC</th><th>GIAO VIỆC</th><th>BẢNG KIỂM</th><th>VI PHẠM</th><th>TỔNG</th><th>XẾP LOẠI</th><th>CHI TIẾT</th></tr></thead><tbody>{rows.length?rows.map((row,index)=><tr key={row.staffId||row.name||index} style={{borderLeft:`6px solid ${row.rankingColor||'#94a3b8'}`}}><td><b>{row.name||'—'}</b><small>{row.position||'—'}</small></td><td>{row.department||'—'}</td><td className="kpi-score-base">{kpiScoreText(row.base)}</td><td className={kpiScoreClass(row.taskScore)}>{kpiScoreText(row.taskScore,true)}</td><td className={kpiScoreClass(row.checklistScore)}>{kpiScoreText(row.checklistScore,true)}</td><td className={kpiScoreClass(row.violationScore)}>{kpiScoreText(row.violationScore)}</td><td className="kpi-total-score">{Number(row.total||0).toFixed(1)}</td><td><span className="kpi-rank-pill" style={{backgroundColor:row.rankingColor||'#6C757D',color:kpiRankTextColor(row.rankingColor)}}>{row.ranking||row.rank||'—'}</span></td><td className="kpi-details-cell">{Array.isArray(row.details)&&row.details.length?<ul>{row.details.map((detail:string,detailIndex:number)=><li key={`${row.staffId||row.name}-${detailIndex}`}>{detail}</li>)}</ul>:<span className="muted">Không có điểm cộng/trừ chi tiết</span>}</td></tr>):<tr><td colSpan={9} className="empty-cell">Không có dữ liệu KPI phù hợp với bộ lọc hiện tại.</td></tr>}</tbody></table></div>}
function KpiDashboard({payload,filters,onCreate,onCreateFeedback,onCreateRule,onEdit,onInline}:{payload:AnyRecord;filters:AnyRecord;onCreate:()=>void;onCreateFeedback:()=>void;onCreateRule:()=>void;onEdit:(row:AnyRecord)=>void;onInline:(body:AnyRecord)=>void}){const rows=recordArray(payload.rows);const summary=payload.summary||{};const rules=((payload.conversionRules||payload.rules||[]) as AnyRecord[]).slice().sort((a,b)=>Number(a.order||0)-Number(b.order||0));const rankCounts=summary.rankCounts||{};const summaryCards=[['Số nhân viên',summary.staffCount??rows.length,'kpi-card-dark'],['KPI bình quân',summary.averageScore??0,'kpi-card-blue'],['Tổng điểm giao việc',summary.totalTaskScore??0,'kpi-card-teal'],['Tổng điểm bảng kiểm',summary.totalChecklistScore??0,'kpi-card-indigo'],['Tổng điểm vi phạm',summary.totalViolationScore??0,'kpi-card-red']];return <div className="module-stack kpi-dashboard"><div className="kpi-formula-bar"><b>CÔNG THỨC KPI CHÍNH THỨC:</b> 100 + điểm giao việc + điểm bảng kiểm + điểm vi phạm <small>(điểm vi phạm được lưu dưới dạng số âm)</small></div><div className="kpi-summary-grid">{summaryCards.map(([label,value,kind])=><div key={String(label)} className={String(kind)}><small>{label}</small><b>{typeof value==='number'?Number(value).toFixed(label==='KPI bình quân'?1:0):value}</b></div>)}</div><div className="kpi-ranking-grid">{rules.map((rule,index)=><div key={rule.ranking||index} style={{backgroundColor:rule.color||'#6C757D',color:kpiRankTextColor(rule.color)}}><b>{rule.ranking||'—'}</b><strong>{rankCounts[rule.ranking]||0}</strong></div>)}</div><div className="panel-card kpi-toolbar"><div><b>{rows.length} nhân sự KPI</b><p className="muted">Đang tính theo khoảng thời gian, bộ phận và nhân viên đã chọn.</p></div><div className="card-actions"><button type="button" className="add-btn" onClick={()=>exportKpiExcel(rows,summary)}>⇩ XUẤT EXCEL</button><button type="button" className="add-btn" onClick={onCreate}>LƯU BẢNG KPI</button><button type="button" className="edit-btn" onClick={onCreateFeedback}>+ GÓP Ý KPI</button><button type="button" className="edit-btn" onClick={onCreateRule}>⚙ QUY ĐỔI XẾP LOẠI</button></div></div><KpiScoreTable rows={rows}/><ReportKpiBars rows={rows}/><div className="kpi-total-strip"><div><b>{summary.totalScore??0}</b><span>Tổng điểm KPI toàn bộ</span></div><div><b>{summary.totalTaskScore??0}</b><span>Tổng điểm giao việc</span></div><div><b>{summary.totalChecklistScore??0}</b><span>Tổng điểm bảng kiểm</span></div><div><b>{summary.totalViolationScore??0}</b><span>Tổng điểm vi phạm</span></div><div><b>{summary.averageScore??0}</b><span>Điểm KPI bình quân</span></div></div><div className="panel-card kpi-conclusion"><h3>📌 KẾT LUẬN KPI</h3><ul><li>{payload.conclusion||'Chưa đủ dữ liệu KPI.'}</li><li>Có {rankCounts['XUẤT SẮC']||0} nhân viên xếp loại XUẤT SẮC, {rankCounts['TỐT']||0} nhân viên xếp loại TỐT.</li><li>Điểm thấp nhất: {rows.length?`${rows.slice().sort((a,b)=>Number(a.total||0)-Number(b.total||0))[0].name} — ${Number(rows.slice().sort((a,b)=>Number(a.total||0)-Number(b.total||0))[0].total||0).toFixed(1)} điểm.`:'Chưa có dữ liệu.'}</li></ul></div><ReportOpinionEditor opinions={(payload.opinions||[]) as AnyRecord[]} filters={filters} formCode="__KPI_MODULE__" formName="KẾT LUẬN / GÓP Ý CỦA QUẢN LÝ" onSave={onInline}/><div className="panel-card"><div className="toolbar-line"><h3>⚙ CẤU HÌNH QUY ĐỔI ĐIỂM</h3><span className="muted">Giữ nguyên ngưỡng và màu đang lưu trong DM_QUYDOI_KPI.</span></div><KpiConversionTable rules={rules} onEdit={onEdit}/></div><div className="panel-card"><h3>GÓP Ý KPI ĐÃ LƯU</h3><DataTable rows={(payload.feedback||[]).map((x:AnyRecord)=>x.data?{...x.data,row_no:x.row_no}:x)} columns={['Mã ý kiến','Từ ngày','Đến ngày','Bộ phận','Nhân viên','Nội dung góp ý','Người nhập']} headers={['Mã','Từ','Đến','Bộ phận','Nhân viên','Nội dung','Người nhập']}/></div></div>}
function ViolationDetailPanel({row,onClose}:{row:AnyRecord;onClose:()=>void}){const evidenceId=row.id||row.legacy_id||row.row_no;return <div className="panel-card violation-detail-panel"><div className="toolbar-line"><div><h3>CHI TIẾT LỊCH SỬ GHI NHẬN LỖI ĐỘT XUẤT / VI PHẠM</h3><p className="muted">Kiểm tra đầy đủ nội dung đã ghi nhận trước khi sửa thông tin hoặc biện pháp khắc phục.</p></div><button type="button" className="filter-reset" onClick={onClose}>ĐÓNG CHI TIẾT</button></div><div className="violation-detail-grid"><div><small>Mã ghi nhận</small><b>{row.id||'—'}</b></div><div><small>Ngày vi phạm</small><b>{formatDate(row.date)}</b></div><div><small>Nhân viên</small><b>{row.person||row.name||'—'} {row.staffId?'('+row.staffId+')':''}</b></div><div><small>Bộ phận</small><b>{row.department||'—'}</b></div><div><small>Lỗi vi phạm</small><b>{row.errorName||row.errorId||'—'}</b></div><div><small>Mức độ</small><Badge value={row.level}/></div><div><small>Điểm trừ</small><b>{row.score??row.points??0}</b></div><div><small>Người ghi nhận</small><b>{row.recorder||'—'}</b></div><div className="wide"><small>Ghi chú / nguyên nhân</small><p>{row.note||'—'}</p></div></div><div className="violation-detail-evidence"><div><b>Ảnh minh chứng</b><EvidenceLinks module="violations" legacyId={evidenceId} fallback={row.imageName||row.imageRef} kind="image"/></div><div><b>Tài liệu minh chứng</b><EvidenceLinks module="violations" legacyId={evidenceId} fallback={row.documentName} kind="document"/></div></div></div>}

function View({module,payload,filters,managerFilter,onCreate,onCreateChecklist,onCreateReminder,onCreateError,onCreateForm,onCreateCriterion,onCreateFeedback,onCreateRule,onEdit,onRemove,onPlanAction,onInline,onOpenAlert,onFilterManager,onFilterApproval,onToggleDaily,onReload}:{module:MainModule;payload:AnyRecord;filters:AnyRecord;managerFilter?:string;onCreate:()=>void;onCreateChecklist:(formCode?:string)=>void;onCreateReminder:()=>void;onCreateError:()=>void;onCreateForm:()=>void;onCreateCriterion:()=>void;onCreateFeedback:()=>void;onCreateRule:()=>void;onEdit:(row:AnyRecord)=>void;onRemove:(row:AnyRecord)=>void;onPlanAction:(op:string,row:AnyRecord)=>void;onInline:(body:AnyRecord)=>void;onOpenAlert:(alert:AnyRecord)=>void;onFilterManager:(managerName:string)=>void;onFilterApproval:()=>void;onToggleDaily:(row:AnyRecord,daily:boolean)=>void;onReload:()=>void}){
 const[taskView,setTaskView]=useState<'tasks'|'approvals'|'reminders'|'workload'>('tasks');
 const[violationDetail,setViolationDetail]=useState<AnyRecord|null>(null);
 if(module==='checklists')return <ScriptChecklistView payload={payload} onCreateChecklist={onCreateChecklist} onCreateForm={onCreateForm} onCreateCriterion={onCreateCriterion} onEdit={onEdit} onRemove={onRemove} onReload={onReload}/>;
 if(module==='reports')return <ScriptReportsView payload={payload} onCreate={onCreate} onEdit={onEdit} onRemove={onRemove} onInline={onInline}/>;
 if(module==='kpi')return <KpiDashboardV2 payload={payload} filters={filters} onCreate={onCreate} onCreateFeedback={onCreateFeedback} onInline={onInline} onReload={onReload}/>;
 const rows=recordArray(payload.rows);
 if(module==='tasks')return <div className="module-stack"><div className="panel-card task-toolbar"><div><b>{payload.total||rows.length} công việc</b><div className="task-approval-summary"><Badge value={`Chờ phê duyệt: ${managerFilter?payload.approvalSummary?.waitingManager||0:0}`}/><Badge value={`Chờ phản hồi: ${managerFilter?payload.approvalSummary?.waitingEmployee||0:0}`}/></div></div><button className="add-btn" onClick={onCreate}>+ TẠO CÔNG VIỆC MỚI</button></div><TaskSummaryCards summary={payload.taskSummary||{total:rows.length,scopeName:managerFilter||'TỔNG THỂ'}}/><div className="task-view-tabs" role="tablist" aria-label="Chọn vùng hiển thị giao việc"><button type="button" className={taskView==='tasks'?'active':''} onClick={()=>setTaskView('tasks')}>📋 GIAO VIỆC</button><button type="button" className={taskView==='approvals'?'active':''} onClick={()=>setTaskView('approvals')}>✅ XIN PHÊ DUYỆT ({managerFilter?payload.approvalSummary?.waitingManager||0:0})</button><button type="button" className={taskView==='reminders'?'active':''} onClick={()=>setTaskView('reminders')}>📝 NHẮC VIỆC &amp; GHI CHÚ</button><button type="button" className={taskView==='workload'?'active':''} onClick={()=>setTaskView('workload')}>👥 KHỐI LƯỢNG</button></div>{taskView==='approvals'&&<TaskApprovalQueue items={payload.approvalItems||[]} managerFilter={managerFilter} onEdit={onEdit} onFilterApproval={onFilterApproval}/>} {taskView==='tasks'&&<div className="task-list">{rows.map(row=><article className="task-card" key={row.row_no}><div className="task-head"><div><span className="eyebrow">{row.assignee||'Chưa giao'} · {row.department||'Chưa chọn bộ phận'}</span><small className="task-assignment">Người giao việc: {row.assigner||'—'}</small><h3>{row.title||'Chưa có tiêu đề'}</h3></div><div className="badge-stack"><Badge value={row.status}/><Badge value={row.evalStatus}/></div></div><div className="task-description"><b>Nội dung / Mô tả</b><p>{row.description||'—'}</p></div><div className="task-meta"><span><b>Mức ưu tiên</b>{row.priority||'—'}</span><span><b>Từ ngày</b>{formatDate(row.startDate)}</span><span><b>Đến ngày</b>{formatDate(row.endDate)}</span><span className="manager-opinion-text"><b>Ý kiến quản lý</b>{row.managerOpinion||'—'}</span></div><div className="task-approval-detail"><div><b>PHÊ DUYỆT / XIN PHÊ DUYỆT</b><Badge value={approvalLabel(row.approvalStatus)}/></div><small>Quản lý: {row.managerName||'Chưa chọn'}</small>{row.approvalRequest&&<p><b>Nội dung xin phê duyệt:</b> {row.approvalRequest}</p>}{row.approvalResponse&&<p><b>Phản hồi quản lý:</b> {row.approvalResponse}</p>}{row.employeeFeedback&&<p><b>Phản hồi nhân viên:</b> {row.employeeFeedback}</p>}</div><div className="task-description"><b>Phương án dự phòng</b><p>{row.backup||'—'}</p></div><div className="evidence-row"><b>Ảnh minh chứng</b><EvidenceLinks module="tasks" legacyId={row.taskId||row.id} fallback={row.imageName} kind="image"/></div><div className="evidence-row"><b>Tài liệu minh chứng</b><EvidenceLinks module="tasks" legacyId={row.taskId||row.id} kind="document"/></div><div className="card-actions"><button className="edit-btn" onClick={()=>onEdit({...row,__module:'taskApproval',approvalAction:'request'})}>XIN PHÊ DUYỆT</button>{isWaitingManager(row.approvalStatus)&&<button className="approval-btn" onClick={()=>onEdit({...row,__module:'taskApproval',approvalAction:'review'})}>PHÊ DUYỆT</button>}{['da phe duyet','yeu cau bo sung','tu choi'].includes(normalize(row.approvalStatus))&&!row.employeeFeedback&&<button className="approval-btn" onClick={()=>onEdit({...row,__module:'taskApproval',approvalAction:'feedback'})}>PHẢN HỒI</button>}<button className="edit-btn" onClick={()=>onEdit(row)}>SỬA / BỔ SUNG</button><button className="danger" onClick={()=>onRemove(row)}>XÓA</button></div></article>)}</div>}{taskView==='workload'&&<WorkloadPanel rows={payload.workload||[]}/>} {taskView==='reminders'&&<ReminderPanel rows={payload.reminders||[]} staff={(payload.staff||[]) as AnyRecord[]} statuses={payload.options?.reminderStatuses||['CHƯA THỰC HIỆN','ĐANG THỰC HIỆN','ĐÃ XONG']} onCreate={onCreateReminder} onEdit={onEdit} onRemove={onRemove} onToggleDaily={onToggleDaily}/>}</div>;
 if(module==='staff')return <div className="module-stack"><div className="panel-card"><div className="toolbar-line"><div><b>{payload.total||rows.length} nhân viên</b><p className="muted">Cột Chức vụ là căn cứ xác định người quản lý phê duyệt. Hợp đồng hết hạn trong 10 ngày sẽ cảnh báo trên màn hình chính.</p></div><button className="add-btn" onClick={onCreate}>+ THÊM NHÂN VIÊN</button></div></div><div className="summary-cards staff-leave-summary"><div><b>{payload.leaveSummary?.annualLeave||0}</b><span>Tổng phép năm</span></div><div><b>{payload.leaveSummary?.taken||0}</b><span>Đã nghỉ</span></div><div><b>{payload.leaveSummary?.remaining||0}</b><span>Còn lại</span></div></div><LeavePlanningPanel rows={(payload.leavePlan||[]) as AnyRecord[]} summary={payload.leavePlanSummary||{}} meta={payload.leavePlanMeta||{}}/><div className="panel-card"><div className="leave-summary-note"><b>PHÉP NĂM</b><span>Mỗi lần nghỉ, bấm <strong>+ NGHỈ PHÉP</strong> ở đúng nhân sự để nhập ngày và số ngày nghỉ. Hệ thống tự cộng dồn, tính số còn lại và giữ lịch sử.</span></div><StaffDirectoryTable rows={rows} onEdit={onEdit} onRemove={onRemove}/></div></div>;
 if(module==='violations')return <div className="module-stack">{violationDetail&&<ViolationDetailPanel row={violationDetail} onClose={()=>setViolationDetail(null)}/>}<div className="panel-card toolbar-line"><b>{payload.total||rows.length} vi phạm</b><div className="card-actions"><button className="add-btn red" onClick={onCreate}>+ GHI NHẬN VI PHẠM</button><button className="edit-btn" onClick={onCreateError}>+ THÊM DANH MỤC LỖI</button></div></div><div className="panel-card"><DataTable rows={rows} columns={['date','person','department','errorName','level','score','recorder','note','imageName','documentName']} headers={['Ngày','Họ tên','Bộ phận','Tên lỗi','Mức độ','Điểm trừ','Người ghi nhận','Ghi chú','Ảnh minh chứng','Tài liệu minh chứng']} actionRender={(row)=><button type="button" className="edit-btn" onClick={()=>setViolationDetail(row)}>XEM CHI TIẾT</button>} onEdit={onEdit} onRemove={onRemove}/></div><div className="panel-card"><h3>Danh mục lỗi vi phạm</h3><DataTable rows={(Array.isArray(payload.errorCatalog)?payload.errorCatalog:[]).map((x:AnyRecord)=>({...x,__module:'violationError'}))} columns={['id','name','department','level','score']} headers={['Mã lỗi','Tên lỗi','Bộ phận','Mức độ','Điểm trừ']} onEdit={onEdit} onRemove={onRemove}/></div></div>;
 if(module==='plans')return <div className="module-stack"><div className="summary-cards"><div><b>{payload.summary?.total||0}</b><span>Kế hoạch</span></div><div><b>{payload.summary?.done||0}</b><span>Hoàn thành</span></div><div><b>{payload.summary?.overdue||0}</b><span>Quá hạn</span></div><div><b>{payload.summary?.openIssues||0}</b><span>Tồn tại mở</span></div></div><div className="panel-card toolbar-line"><b>{payload.total||rows.length} kế hoạch</b><button className="add-btn" onClick={onCreate}>+ THÊM KẾ HOẠCH</button></div><div className="plan-list">{rows.map(row=><article className="plan-card" key={row.row_no}><div><span className="eyebrow">{row.type} · {row.department||'Chưa chọn bộ phận'} · {row.owner||'Chưa giao'}</span><h3>{row.content||'Chưa có nội dung'}</h3><p>{row.description||'—'}</p><p className="muted">Kết quả: {row.result||'—'} · Ghi chú: {row.note||'—'}</p></div><div className="plan-side"><Badge value={row.status}/><small>{row.type==='TUẦN'&&planWeekdayLabel(row.fromDate)?`${planWeekdayLabel(row.fromDate)} · `:''}{formatDate(row.fromDate)} → {formatDate(row.toDate)}</small><div className="card-actions"><button className="edit-btn" onClick={()=>onEdit(row)}>SỬA</button><button className="edit-btn" onClick={()=>onPlanAction('complete',row)}>HOÀN THÀNH</button><button className="edit-btn" onClick={()=>onPlanAction('carry',row)}>↻ {normalize(row.type).includes('thang')?'THÁNG SAU':'TUẦN SAU'}</button><button className="edit-btn" onClick={()=>onPlanAction('reset',row)}>ĐẶT LẠI</button><button className="danger" onClick={()=>onRemove(row)}>XÓA</button></div></div></article>)}</div><div className="panel-card"><div className="toolbar-line"><h3>Tồn tại / Sự cố / Kiến nghị</h3><button className="add-btn" onClick={()=>onEdit({__module:'issues',id:'',date:new Date().toISOString().slice(0,10),status:'CHƯA KHẮC PHỤC'})}>+ THÊM TỒN TẠI</button></div><DataTable rows={(payload.issues||[]).map((x:AnyRecord)=>({...x,__module:'issues'}))} columns={['id','date','department','issue','cause','action','owner','deadline','status','recommendation','note']} headers={['Mã','Ngày','Bộ phận','Nội dung','Nguyên nhân','Khắc phục','Phụ trách','Hạn','Trạng thái','Kiến nghị','Ghi chú']} onEdit={onEdit} onRemove={onRemove}/></div></div>;
 if(module==='alerts')return <div className="panel-card"><div className="toolbar-line"><div><b>{payload.total||rows.length} cảnh báo</b><p className="muted">Bấm tên quản lý để lọc các yêu cầu đang chờ người đó phê duyệt; bấm MỞ &amp; XỬ LÝ để phản hồi ngay.</p></div><small>Quá hạn · Hợp đồng · Chờ phê duyệt · Chờ phản hồi</small></div><AlertTable rows={rows} onOpenAlert={onOpenAlert} onFilterManager={onFilterManager}/></div>;
 return <div className="panel-card"><DataTable rows={rows}/></div>;
}

function ReminderPanel({rows,onCreate,onEdit,onRemove,onToggleDaily,staff,statuses}:{rows:AnyRecord[];onCreate:()=>void;onEdit:(row:AnyRecord)=>void;onRemove:(row:AnyRecord)=>void;onToggleDaily:(row:AnyRecord,daily:boolean)=>void;staff:AnyRecord[];statuses:string[]}){const[query,setQuery]=useState('');const[person,setPerson]=useState('');const[status,setStatus]=useState('');const[detail,setDetail]=useState<AnyRecord|null>(null);const visible=rows.filter(row=>{const hay=normalize([row.title,row.note].filter(Boolean).join(' '));return(!query||hay.includes(normalize(query)))&&(!person||sameValue(row.person,person))&&(!status||sameValue(row.status,status));});return <div className="panel-card"><div className="toolbar-line"><h3>NHẮC VIỆC / GHI CHÚ (không tính KPI)</h3><button className="edit-btn" onClick={onCreate}>+ THÊM NHẮC VIỆC</button></div><div className="reminder-filter-bar" aria-label="Tìm kiếm nhắc việc"><label>Tìm tiêu đề / ghi chú<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Gõ từ khóa để lọc..." /></label><label>Người liên quan<SmartStaffPicker staff={staff} value={person} onChange={setPerson} placeholder="Gõ tên → lọc → chọn" showPosition/></label><label>Trạng thái<SmartOptionPicker options={statuses} value={status} onChange={setStatus} placeholder="Gõ trạng thái → chọn"/></label>{(query||person||status)&&<button type="button" className="filter-reset" onClick={()=>{setQuery('');setPerson('');setStatus('')}}>XÓA LỌC</button>}<span className="reminder-result-count">{visible.length}/{rows.length} mục</span></div>{detail&&<div className="panel-card reminder-detail-panel"><div className="toolbar-line"><div><h3>CHI TIẾT NHẮC VIỆC</h3><p className="muted">Theo dõi nội dung, minh chứng và trạng thái nhắc việc.</p></div><button type="button" className="filter-reset" onClick={()=>setDetail(null)}>ĐÓNG</button></div><div className="reminder-detail-grid"><div><small>Ngày nhắc</small><b>{formatDate(detail.date)}</b></div><div><small>Tiêu đề</small><b>{detail.title||'—'}</b></div><div><small>Người liên quan</small><b>{detail.person||'—'}</b></div><div><small>Trạng thái</small><Badge value={detail.status}/></div><div><small>Nhắc hàng ngày</small><b>{enabledFlag(detail.daily||detail.remindDaily)?'ĐANG BẬT':'ĐANG TẮT'}</b></div><div className="wide"><small>Nội dung / Ghi chú</small><p>{detail.note||'—'}</p></div></div><div className="reminder-detail-evidence"><div><b>Ảnh minh chứng</b><EvidenceLinks module="reminders" legacyId={detail.id||detail.legacy_id||detail.row_no} kind="image"/></div><div><b>Tài liệu minh chứng</b><EvidenceLinks module="reminders" legacyId={detail.id||detail.legacy_id||detail.row_no} kind="document"/></div></div></div>}<DataTable rows={visible.map(x=>({...x,__module:'reminders'}))} columns={['date','title','note','person','status']} headers={['Ngày nhắc','Tiêu đề','Nội dung / Ghi chú','Người liên quan','Trạng thái']} actionRender={row=><><button type="button" className="edit-btn" onClick={()=>setDetail(row)}>XEM CHI TIẾT</button><button type="button" className="edit-btn" onClick={()=>onToggleDaily(row,!enabledFlag(row.daily||row.remindDaily))}>{enabledFlag(row.daily||row.remindDaily)?'TẮT NHẮC HÀNG NGÀY':'BẬT NHẮC HÀNG NGÀY'}</button></>} onEdit={onEdit} onRemove={onRemove}/></div>;}
 function Performance({rows}:{rows:AnyRecord[]}){return <div className="panel-card"><h3>📊 TỔNG HỢP HIỆU SUẤT NHÂN SỰ — MỐC 100 ĐIỂM</h3><DataTable rows={rows} columns={['name','totalTasks','completed','overdue','excellent','good','fair','poor','bad','total','rank']} headers={['Nhân viên','Tổng CV','Hoàn thành','Quá hạn','Xuất sắc','Tốt','Khá','Chưa đạt','Kém','Tổng điểm','Xếp loại']}/></div>;}

function reportStatusClass(value:any){const n=normalize(value);if(n.includes('qua han')||n.includes('khong dat')||n.includes('tu choi'))return 'report-status-danger';if(n.includes('hoan thanh')||n.includes('da phe duyet')||n.includes('da khac phuc')||n.includes('xuat sac')||n==='tot')return 'report-status-success';if(n.includes('dang')||n.includes('cho phe duyet'))return 'report-status-info';if(n.includes('yeu cau bo sung')||n.includes('chua'))return 'report-status-warning';return 'report-status-neutral'}
function reportStatusOptions(kind:string,current:any){const values=kind==='TASK'?['CHƯA BẮT ĐẦU','ĐANG LÀM','ĐANG THỰC HIỆN','ĐÃ HOÀN THÀNH','HOÀN THÀNH','QUÁ HẠN']:kind==='ISSUE'?['CHƯA XỬ LÝ','ĐANG XỬ LÝ','ĐÃ XỬ LÝ','ĐÃ KHẮC PHỤC','QUÁ HẠN']:['CHƯA BẮT ĐẦU','ĐANG THỰC HIỆN','HOÀN THÀNH','QUÁ HẠN','CHUYỂN TIẾP'];return Array.from(new Set([current,...values].filter(Boolean))) as string[]}
function ReportApprovalCell({row}:{row:AnyRecord}){const approvalStatus=text(row.approvalStatus)||'CHƯA XIN Ý KIẾN';const approvalDecision=text(row.approvalDecision);const managerName=text(row.managerName);const request=text(row.approvalRequest);const response=text(row.approvalResponse||row.managerOpinion||row.qlNote);return <div className="report-approval-cell"><div className="report-approval-status"><small>Trạng thái phê duyệt</small><Badge value={approvalLabel(approvalStatus)}/></div>{approvalDecision&&approvalDecision!==approvalStatus&&<div className="report-approval-status"><small>Kết quả phê duyệt</small><Badge value={approvalLabel(approvalDecision)}/></div>}{managerName&&<p><b>Lãnh đạo:</b> {managerName}</p>}{request&&<p><b>Nội dung xin:</b> {request}</p>}{response&&<p><b>Ý kiến lãnh đạo:</b> {response}</p>}</div>}
function ReportInlineTable({rows,kind,onSave}:{rows:AnyRecord[];kind:'PLAN'|'TASK';onSave:(payload:AnyRecord)=>void}){return <div><p className="report-autosave-hint">Các ô trạng thái, đánh giá và ghi chú sẽ tự động lưu khi rời khỏi ô nhập.</p><div className="table-wrap"><table className="report-inline-table"><thead><tr><th>STT</th><th>Người thực hiện / phụ trách</th><th>Tiêu đề / nội dung công việc</th><th>Thời hạn</th><th>Trạng thái công việc</th><th>Đánh giá / kết quả</th><th>Phê duyệt / ý kiến lãnh đạo</th></tr></thead><tbody>{rows.length?rows.map((row,index)=><InlineReportRow key={row.id||row.row_no||index} row={row} kind={kind} index={index} onSave={onSave}/>):<tr><td colSpan={7} className="empty-cell">Chưa có dữ liệu trong khoảng thời gian đã chọn.</td></tr>}</tbody></table></div></div>}
function InlineReportRow({row,kind,index,onSave}:{row:AnyRecord;kind:'PLAN'|'TASK';index:number;onSave:(payload:AnyRecord)=>void}){const[status,setStatus]=useState(row.status||'');const[evalStatus,setEvalStatus]=useState(row.evalStatus||'');const[note,setNote]=useState(kind==='TASK'?(row.qlNote||row.managerOpinion||row.approvalResponse||row.note||''):(row.note||''));const save=()=>onSave({kind,id:row.id,row_no:row.row_no,planType:row.type,status,evalStatus,note});const title=text(row.title||row.content)||'—';const description=text(row.description);const deadline=row.endDate||row.toDate;return <tr><td>{index+1}</td><td><b>{text(row.assignee||row.owner)||'—'}</b>{row.department&&<small className="report-row-meta">{row.department}</small>}</td><td><div className="report-row-title">{title}</div>{description&&<div className="report-row-description"><b>Nội dung / Mô tả:</b> {description}</div>}</td><td>{formatDate(deadline)}{row.startDate||row.fromDate?<small className="report-row-meta">Từ {formatDate(row.startDate||row.fromDate)}</small>:null}</td><td><select className={'report-status-select '+reportStatusClass(status)} value={status} onChange={e=>setStatus(e.target.value)} onBlur={save}>{reportStatusOptions(kind,status).map(x=><option key={x} value={x}>{x}</option>)}</select></td><td><div className="report-evaluation-cell">{kind==='TASK'?<select className={'report-status-select '+reportStatusClass(evalStatus)} value={evalStatus} onChange={e=>setEvalStatus(e.target.value)} onBlur={save}>{['','XUẤT SẮC','TỐT','KHÁ','TRUNG BÌNH','CHƯA ĐẠT','CHƯA ĐẠT_LÀM LẠI','KÉM','QUÁ HẠN'].map(x=><option key={x||'empty'} value={x}>{x||'CHƯA ĐÁNH GIÁ'}</option>)}</select>:<Badge value={text(row.result)||'CHƯA CẬP NHẬT'}/>}<label className="report-inline-note-label">{kind==='TASK'?'Ghi chú / Phản hồi quản lý':'Ghi chú / Kết quả'}<textarea value={note} onChange={e=>setNote(e.target.value)} onBlur={save} placeholder="Nhập nội dung..." /></label></div></td><td><ReportApprovalCell row={row}/></td></tr>}
function ReportNextWeekTable({rows,onSave}:{rows:AnyRecord[];onSave:(payload:AnyRecord)=>void}){return <div><p className="report-autosave-hint">Danh sách lấy từ kế hoạch, giao việc và tồn tại còn mở của tuần kế tiếp. Trạng thái và ghi chú tự động lưu khi rời khỏi ô nhập.</p><div className="table-wrap"><table className="report-inline-table report-next-week-table"><thead><tr><th>Nguồn</th><th>Người phụ trách</th><th>Tiêu đề / nội dung công việc</th><th>Bắt đầu</th><th>Hạn</th><th>Trạng thái</th><th>Phê duyệt / ý kiến lãnh đạo</th><th>Ghi chú / kết quả</th></tr></thead><tbody>{rows.length?rows.map((row,index)=><NextWeekReportRow key={row.id||row.row_no||index} row={row} onSave={onSave}/>):<tr><td colSpan={8} className="empty-cell">Chưa có công việc hoặc nội dung cần theo dõi trong tuần kế tiếp.</td></tr>}</tbody></table></div></div>}
function NextWeekReportRow({row,onSave}:{row:AnyRecord;onSave:(payload:AnyRecord)=>void}){const kind=(row.kind||'PLAN') as 'PLAN'|'TASK'|'ISSUE';const[status,setStatus]=useState(row.status||'');const[note,setNote]=useState(row.note||'');const save=()=>onSave({kind,id:row.id,row_no:row.row_no,planType:row.type,status,note});const title=text(row.title||row.content||row.issue)||'—';const description=text(row.description);return <tr><td><b>{text(row.source)||'KẾ HOẠCH'}</b><small className="report-row-meta">{text(row.type)}</small></td><td>{text(row.assignee||row.owner)||'—'}</td><td><div className="report-row-title">{title}</div>{description&&<div className="report-row-description"><b>Nội dung / Mô tả:</b> {description}</div>}</td><td>{formatDate(row.fromDate||row.startDate||row.date)}</td><td>{formatDate(row.toDate||row.endDate||row.deadline)}</td><td><select className={'report-status-select '+reportStatusClass(status)} value={status} onChange={e=>setStatus(e.target.value)} onBlur={save}>{reportStatusOptions(kind,status).map(x=><option key={x} value={x}>{x}</option>)}</select></td><td><ReportApprovalCell row={row}/></td><td><textarea className="report-next-week-note" value={note} onChange={e=>setNote(e.target.value)} onBlur={save} placeholder="Nhập ghi chú / kết quả..." /></td></tr>}

function EvidenceLinks({module,legacyId,fallback,kind='all',allowDelete=true}:{module:string;legacyId:any;fallback?:any;kind?:'all'|'image'|'document';allowDelete?:boolean}){const[files,setFiles]=useState<AnyRecord[]>([]);const[busy,setBusy]=useState('');const load=useCallback(()=>{if(!legacyId){setFiles([]);return Promise.resolve();}return fetch('/api/evidence?module='+encodeURIComponent(module)+'&legacy_id='+encodeURIComponent(String(legacyId)),{cache:'no-store'}).then(r=>r.json()).then(j=>setFiles(j.files||[])).catch(()=>setFiles([]));},[module,legacyId]);useEffect(()=>{void load();},[load,fallback]);async function remove(file:AnyRecord){if(!window.confirm('Xóa tệp minh chứng "'+file.file_name+'"?'))return;setBusy(String(file.id));try{const r=await fetch('/api/evidence?id='+encodeURIComponent(String(file.id)),{method:'DELETE'});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Không xóa được tệp');setFiles(current=>current.filter(x=>x.id!==file.id));}catch(error){window.alert(error instanceof Error?error.message:'Không xóa được tệp');}finally{setBusy('');}}const visible=files.filter(file=>kind==='all'||(kind==='image'?String(file.mime_type||'').startsWith('image/'):!String(file.mime_type||'').startsWith('image/')));return <span className="evidence-links">{fallback&&<span className="muted">{text(fallback)}</span>}{visible.map(file=><span className="evidence-item" key={file.id}><a href={file.url} target="_blank" rel="noreferrer">📎 {file.file_name}</a>{allowDelete&&<button type="button" className="evidence-delete" disabled={busy===String(file.id)} onClick={()=>remove(file)}>{busy===String(file.id)?'ĐANG XÓA':'XÓA'}</button>}</span>)}{!fallback&&!visible.length&&<span className="muted">Chưa có tệp</span>}</span>;}

function DataTable({rows,columns,headers,onEdit,onRemove,actionRender}:{rows:AnyRecord[];columns?:string[];headers?:string[];onEdit?:(row:AnyRecord)=>void;onRemove?:(row:AnyRecord)=>void;actionRender?:(row:AnyRecord)=>React.ReactNode}){const cols=columns||Array.from(new Set(rows.flatMap(x=>Object.keys(x.data||x)))).filter(x=>x!=='row_no'&&x!=='legacy_id'&&x!=='data').slice(0,14);return <div className="table-wrap"><table><thead><tr>{(headers||cols).map((x,i)=><th key={i}>{x}</th>)}{(onEdit||onRemove||actionRender)&&<th>Thao tác</th>}</tr></thead><tbody>{rows.length?rows.map((row,i)=><tr key={row.row_no||row.id||i}>{cols.map(c=><td key={c} title={text(row[c]??row.data?.[c])}>{text(row[c]??row.data?.[c])||'—'}</td>)}{(onEdit||onRemove||actionRender)&&<td className="actions-cell">{actionRender?.(row)}{onEdit&&<button className="edit-btn" onClick={()=>onEdit(row)}>SỬA</button>}{onRemove&&<button className="danger" onClick={()=>onRemove(row)}>XÓA</button>}</td>}</tr>):<tr><td colSpan={cols.length+1} className="empty-cell">Chưa có dữ liệu.</td></tr>}</tbody></table></div>;}

function EvidenceUpload(){return <div className="form-grid wide evidence-upload"><label className="form-field wide evidence-label">Ảnh minh chứng<input type="file" name="evidenceImageFile" accept="image/jpeg,image/png,image/webp"/><small>JPG, PNG hoặc WEBP, tối đa 8 MB.</small></label><label className="form-field wide evidence-label">Tài liệu minh chứng<input type="file" name="evidenceDocumentFile" accept="application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/zip,application/x-7z-compressed,application/x-rar-compressed,application/octet-stream,application/x-msdownload"/><small>PDF, DOC, DOCX, XLS, XLSX, ZIP, 7Z, RAR hoặc EXE, tối đa 8 MB.</small></label></div>;}

function ChecklistScoringTable({details,change}:{details:AnyRecord[];change:(key:string,value:any)=>void}){
 const update=(index:number,key:string,value:any)=>change('details',details.map((item,position)=>position===index?{...item,[key]:value}:item));
 const markAll=()=>change('details',details.map(item=>({...item,result:'ĐẠT'})));
 const pass=details.filter(item=>normalize(item.result)==='dat').length;const fail=details.filter(item=>normalize(item.result)==='khong dat'||normalize(item.result)==='kem').length;const na=details.filter(item=>normalize(item.result)==='khong ap dung'||normalize(item.result)==='n/a').length;const evaluated=pass+fail;const rate=evaluated?Math.round(pass*10000/evaluated)/100:0;const kpi=rate>=95?5:rate>=90?3:rate>=80?0:rate>=70?-3:-5;
 const incomplete=details.map((item,index)=>!normalize(item.result)?index+1:['khong dat','kem'].includes(normalize(item.result))&&!text(item.note)?index+1:0).filter(Boolean) as number[];
 return <div className="wide checklist-score-panel"><div className="toolbar-line checklist-score-head"><div><b>CHI TIẾT PHIẾU GIÁM SÁT</b><small>Chọn kết quả cho từng tiêu chí; ghi chú bắt buộc khi Không đạt/Kém.</small></div><button type="button" className="edit-btn" onClick={markAll}>✓ ĐÁNH DẤU TẤT CẢ ĐẠT</button></div>{incomplete.length>0&&<div className="validation-alert" role="alert" aria-live="assertive"><strong>⚠ CHƯA THỂ LƯU PHIẾU</strong><span>{incomplete.some(index=>!normalize(details[index-1]?.result))?'Còn tiêu chí chưa chọn kết quả. ':''}{incomplete.some(index=>['khong dat','kem'].includes(normalize(details[index-1]?.result))&&!text(details[index-1]?.note))?'Mọi tiêu chí KHÔNG ĐẠT/KÉM phải có ghi chú lỗi.':''}</span><small>Tiêu chí cần kiểm tra: {incomplete.slice(0,10).join(', ')}{incomplete.length>10?'…':''}</small></div>}<div className="table-wrap checklist-score-table"><table><thead><tr><th>STT</th><th>NỘI DUNG</th><th>NỘI DUNG CHI TIẾT</th><th>KẾT QUẢ</th><th>HÌNH ẢNH LỖI</th><th>GHI CHÚ</th></tr></thead><tbody>{details.length?details.map((item,index)=>{const result=normalize(item.result);const invalid=!result||(['khong dat','kem'].includes(result)&&!text(item.note));return <tr key={item.criterionCode||item.id||index} className={invalid?'checklist-invalid-row':''}><td>{item.order||index+1}</td><td><b>{item.content||'—'}</b>{item.group&&<small>{item.group}</small>}</td><td>{item.detail||'—'}</td><td><select aria-invalid={invalid} value={item.result||''} onChange={e=>update(index,'result',e.target.value)}><option value="">-- Chọn --</option><option>ĐẠT</option><option>KHÔNG ĐẠT</option><option>KHÔNG ÁP DỤNG</option></select></td><td>{normalize(item.allowImage||'Có')!=='khong'&&normalize(item.allowImage||'Có')!=='no'?<label className="checklist-evidence-button">📷 Chụp/Tải ảnh<input type="file" data-checklist-detail-image="true" data-criterion-code={item.criterionCode||item.id||''} accept="image/jpeg,image/png,image/webp" onChange={e=>update(index,'errorImage',e.target.files?.[0]?.name||'')}/></label>:<span>—</span>}{item.errorImage&&<small className="checklist-file-name">{item.errorImage}</small>}</td><td><input aria-invalid={invalid&&['khong dat','kem'].includes(result)} value={item.note||''} onChange={e=>update(index,'note',e.target.value)} placeholder="Ghi chú; bắt buộc khi Không đạt"/></td></tr>;}):<tr><td colSpan={6} className="empty-cell">Chưa có tiêu chí. Hãy chọn một phiếu giám sát.</td></tr>}</tbody></table></div><div className="checklist-score-summary"><span>Tổng tiêu chí: <b>{details.length}</b></span><span>Đã chấm: <b>{evaluated+na}</b></span><span>Đạt: <b className="text-ok">{pass}</b></span><span>Không đạt: <b className="text-danger">{fail}</b></span><span>N/A: <b>{na}</b></span><span>Tỷ lệ: <b>{rate}%</b></span><span>Điểm KPI: <b>{kpi}</b></span></div></div>;
}

function ManagerEvaluationPanel({form}:{form:AnyRecord}){const evaluation=form.evalStatus||'CHƯA BẮT ĐẦU';return <section className="task-approval-evaluation" aria-labelledby="manager-evaluation-title"><div className="task-approval-evaluation-head"><div><b id="manager-evaluation-title">ĐÁNH GIÁ QUẢN LÝ</b><small>Phần đánh giá được xem và lưu trong thao tác phê duyệt. Lịch sử các cấp quản lý vẫn được giữ trong hồ sơ.</small></div><Badge value={evaluation}/></div><div className="task-approval-evaluation-grid"><div><small>Đánh giá quản lý hiện tại</small><b>{evaluation}</b></div><div><small>Quản lý đánh giá</small><b>{form.evaluationCurrentBy||form.managerName||'—'}</b></div><div><small>Kết quả phê duyệt</small><Badge value={approvalLabel(form.approvalStatus)}/></div><div><small>Thời gian đánh giá</small><b>{formatDate(form.evaluationCurrentAt||form.approvalReviewedAt)}</b></div></div><p className="task-approval-evaluation-note">Khi quản lý chọn <b>ĐÃ PHÊ DUYỆT</b>, <b>YÊU CẦU BỔ SUNG</b> hoặc <b>TỪ CHỐI</b> và bấm lưu, hệ thống mới ghi nhận đánh giá hiện tại và phát cảnh báo tiếp theo.</p></section>}

